INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1029576-math202', 'stk-user7238', 'MATH 202', 'info', '{"desc": "الكورس اخذه هذا السمستر بعد ماانتهيت\nالكورس يتكلم عن المعادلات التفاضليه وطرق حلها\nالكورس جداً سهل ومافيه اي صعوبه\nواغلب التركات تجي من كورسات ثانيه بالتحديد 001 و102", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/2", "user": "user7238", "ts": 1335614927000, "tid": 120616, "pn": 2}}', 1335614927000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1087618-math202', 'stk-cesar_peace', 'MATH 202', 'info', '{"desc": "-\n\nالكتاب المستخدم : الكتاب لا انصح به على كل الأحوال , وهذا لا يمنع من الرجوع إليه في بعض االجزئيات\n\nجودة المقرر : الكورس بشكل عام سهل و أغلب تريكاته تكون من 101 + ماث الأوريـا\n\nالمواضيع التي يتكلم عنها المقرر : طرق حل المعادلات التفاضلية بشتى أنواعها\n\nكيف أحل المعادلات في هذا الكورس ؟ : عبارة عن خطوات معينة تتبعها في حل أي مسألة ( معرفة البروسيجر شيء مهم لحل المسائل )\n\nنوت المدرس مهم جدا لإنه راح يعطيك البروسيجر بشكل سلس أكثر من الكتاب ولآيمنع من النوتات الخارجية\n\nالكورس غالبا أفرجه عالي جدا لـ سهولته , لذآ حآول تجمع درجات as many as u can\n\nبالتوفيق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/3", "user": "CeSaR_PeaCe", "ts": 1346888943000, "tid": 120616, "pn": 3}}', 1346888943000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1088735-math202', 'stk-user5643', 'MATH 202', 'info', '{"desc": "طبعا وجهة نظر تخالف راي اخوي سيزار\n\nاشوف الكتاب جدا جدا ممتاز و يغنيك عن اي نوت\n\nمثل كورسات الماث اللي قبل\n\nكتاب + مانيوال سولوشن + اولد اقزامز = قريد عالي\n\nو بالطبع فيه بعض النوتات الخارجيه كويسه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/4", "user": "user5643", "ts": 1347052339000, "tid": 120616, "pn": 4}}', 1347052339000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381732-math202', 'stk-abo_ali', 'MATH 202', 'info', '{"desc": "جودة المقرر بشكل عام\nمدري وش اقول , لكن بكل بساطه , منهج ماناسبني ابدن , حسيت فيه كمية غباء غير طبيعيه 😦\n\nالمواضيع التي يغطيها المقرر\nبشكل عام دفرنشل اكويجنز , وطرق حلها ,\n\nالكتاب المستخدم للمقرر\nجيد الى حدن ما ماغير انه مختصر الكثير من الخطوات في الحل 😦\n\nالأسئلة والأمثلة المستخدمة في المقرر\nمدري\n\nمدى فائدته في الناحية التطبيقية\nالرياضيات كله على بعضه ماله داعي في الحياة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/12", "user": "Abo_Ali", "ts": 1403434782000, "tid": 120616, "pn": 12}}', 1403434782000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1382412-math202', 'stk-user8577', 'MATH 202', 'info', '{"desc": "Math202\n\nمادة تتكلم عن المعادلات اللي فيها مشتقة وطرق حلها … مادة سهلة الفهم والدراسة.\n\nالمواضيع التي يغطيها المقرر:\nالمادة تعلمك طرق مختلفة لحل معادلات الإشتقاق هذي بمختلف أنواعها و أشكالها.\n\nالكتاب المستخدم للمقرر:\nاستخدمته في بعض الدروس وكان جيد … بس فيه نوت للحميدي يغطي كل اللي في الكتاب ممكن تستفيد منه.\n\nكورس سهل كله عبارة عن “بروسيجر” بمعنى إذا المعادلة عندك شكلها كذا تحل بالطريقة الفلانية وهكذا لكل طريقة.\n\nالكورس أفرجه ممكن يكون عالي وخاصة ميجر1 لان دروسه سهلة فلا تضيعه … رأيي أفضل طريقة لدراسة إفهم الكونسبت و روح للاولد اكزامز.\n\nالمادة بسهولة ممكن تفهمها سلف ستدي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/13", "user": "user8577", "ts": 1403691601000, "tid": 120616, "pn": 13}}', 1403691601000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1407757-math202', 'stk-guest', 'MATH 202', 'info', '{"desc": "مادة لطيفة بشكل عام، مافيها صعوبة تذكر ويمكن متيريل الفاينل هو أسوء شي بسبب طول خطوات الحل بشكل مزعج ، الكتاب ما عجبني الصراحة كنت أذاكر من نوت الحميدي ونوت الدكتور جمال الاسماعيل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/15", "user": "Guest", "ts": 1414345094000, "tid": 120616, "pn": 15}}', 1414345094000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421301-math202', 'stk-user8713', 'MATH 202', 'info', '{"desc": "بسم الله الرحمن الرحيم\nاللهم صل على محمد و آله المعصومين\n\nالمادة: math 202 Differential Equation\nالفصل: 132 & 141 مرتين\n\nالمحتوى:\n\nالمادة اسمها المعادلات التفاضلية أي انه معادلات فيها دوال مشتقة مرة أو مرتين أو أكثر،\n\nو المطلوب هو حل المعادلة أي ايجاد الدالة الأصية (بدون مشتقة).\n\nفي البداية تأخذ معادلة تفاضلية من الرتبة الأولى يعني أعلى مشتقة في المعادلة هي المشتقة الأولى.\n\nثم تأخذ التطبيقات على الرتبة الأولى، توجد عدة تطبيقات و لكن تأخذ فقط تطبيقين\n\n(معدل النمو و الأضمحلال و قانون معدل انخفاض درجة حرارة الأجسام).\n\nثم تبدأ بالرتب العالية (الرتبة الثانية و أكثر) بداية من ايجاد الحل الثاني للرتبة الثانية و تأخذ طرق أخرى للحل.\n\nثم تأخذ الحل بالستخدام المتسلسلات غير المنتهية.\n\nأما الفصل الأخير فيتحدث عن الحل بالستخدام المصفوفات.\n\nالواجبات:\n\nواجب واحد اسبوعيا أو حسب الدكتور طبعا الطلاب تعودوا على الواجبات الأونلاين في الرياضيات،\n\nو لكن في 202 تكون الواجبات كتابة،و هنا تكمن الطامة الكبرى لأنه طـــــــــــــــويــــــــــــــــل جـــــــــــــــــــدا،\n\nبل لايمكن تصور مدى طوله، و لكن دعني أقرب لكم ما أعنيه.\n\nأسبوعيا الواجب تحله في معدل 12 ورقة A4، و أحيانا يكون فقط 4 أوراق و كثير من الأحيان يكون\n\n15 ورقة و أكثر. فالحذر الحذر لاتتركوه بل حلُوه و لوكان في ذلك حتفكم لما له من الأهمية القصوى\n\nإذ أنه_حل الواجب_ يغنيك عن المذاكرة. طبعا يوجد سلوشن و لكنه في أحيان كثيرة لا يسمن و لا يغني من جوع.\n\nوصف المادة و كيفية الحصول على درجة تثلج الصدر:\n\nبصراحة المادة كانت جدا ممتعة لكن الواجب نقص هذه المتعة عليه ما يستحق\n\nو كذلك المادة سهلة و مادة قريد فلا تفوتها يا بني.\n\nأول شيء حل الأمثلة اللي في وسط الدرس ثم حل الواجب الذي هو مفتاح القريد العالي بل مفتاح الـ A+ فلا تتركوه.\n\nإذا قرب الأختبار عليك بالإختبارات السابقة حل و حل و حل و حل و حل حتى تجعل المادة تمشي في عروقك.\n\nصدقوني يا شباب المادة ذي خرطية فلا تفوتوها.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/19", "user": "user8713", "ts": 1421936388000, "tid": 120616, "pn": 19}}', 1421936388000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1436096-math202', 'stk-user9306', 'MATH 202', 'info', '{"desc": "السمستر 151\n\nالمياجر:-كومن وطريقة المذاكره راح تكن من اسئلة الكتاب لكن في الميجر راح تكن اصعب شوي.\n\nالفاينل:- نفس الميجر.\n\nالكويزات:- انا كنت عند ناصر تاتار كانت كويزاته سؤال واحد سهل كل الطلاب يجبن فيه فل مارك يعني لاتشيل هم .\n\nالهوموركات:- هنا تجي المشكلة العصيبه الكرس كان حل لكن الهمركات نغصت علي الصراحة لان احنا متعودين من الاوريا الى 201 على اونلاين هومورك بس في 202 راح يكون كتابي ولا احد يسحب عليه لان يمثل جزء كبير من المذاكرة +اذا ذاكرت اسئلة خارجية مومن الهومورك +الالد اقزام يمكن تجيب درجة خياليه\n\nنصيحة اخيرة:-\nالمادة ذي سهلة والكونسب حقها بسيط جدا لذلك فرصة انك تجيب فيها قريد عالي لذلك كثير من الشباب يشوفنها سهلة ويسحبون عليها وهم اللي صعبوها على انفسهم لانهم ما استفادا من سهولتها وذا فيه في الجامعة مادة قريد ال202 تعتبر واحده منهم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/20", "user": "user9306", "ts": 1450260080000, "tid": 120616, "pn": 20}}', 1450260080000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1470929-math202', 'stk-m_nd_m', 'MATH 202', 'info', '{"desc": "يعتمد على مستواك الأكاديمي و جديتك في المتابعة أول بأول هذا أول شي\n\nفكر فيها… المادتين فيهم ميجرين… ممكن تكون المواعيد متقاربة… و فيهم هومورك (ورقي)… واحد من الشباب اخذها (CE) الصيف الماضي يقول الهوموركات تسلمها أسبوعيًا… و الماث بعض الدكاترة ما يرحمون بالهومورك\n\nأيضًا نقطة آخرى مهمة… الأولوية لك أنك تنزل CE لأنها تفتح مواد بالتخصص مهمة عكس الماث اللي ما يفتح غير ماث 301\n\nهذه نقاط مهمة لازم تاخذها بالحسبان و آخر شي استخير و سوي اللي ترتاح له\n\nإذا في أسئلة إضافية ممكن نحول على الخاص أو تنشأ موضوع نتناقش فيه أحسن عشان ما نشوه الصفحة\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/27", "user": "M_nd_m", "ts": 1491318724000, "tid": 120616, "pn": 27}}', 1491318724000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1521739-math202', 'stk-ahm2d1', 'MATH 202', 'info', '{"desc": "Term 192\n\nجودة المقرر بشكل عام: الكورس بشكل عام يعتبر متوسط ، دروس ميجر ١ مره سهله وبسيطه وتعتبر اسهل شيء في الكورس وبعدها يبدا يصعب لين دروس الفاينل. ( تقدر تقول زي اي كورس ماث ).\n\nالمواضيع التي يغطيها المقرر: دروس ميجر ١ تتكلم عن كيف توجد حلول المعادلة اللي من الدرجه الاولى. وبتاخذ اكثر من طريقه طبعا طريقة الحل تعتمد على نوع المعادلة. وميجر ٢ نفس الشيء بس بتكون من الدرجه الثانيه واكثر. والفاينل بيكون كيف تجيب الحلول من خلال الماتركس او السيريز.\n\nالأسئلة والأمثلة المستخدمة في المقرر: الكتاب ممتاز مره من ناحية الاسئله بس من ناحية الشرح سيء.\n\nمدى فائدته في الناحية التطبيقية: فادني في مادة ME 311 - Fluid Mechanics كان عندنا واجب وكان لازم احل المعادلة باستخدام الطرق الي اخذناها في الكورس هذا.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/29", "user": "Ahm2d1", "ts": 1588528268000, "tid": 120616, "pn": 29}}', 1588528268000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522356-math202', 'stk-nasalmz', 'MATH 202', 'info', '{"desc": "term 192\n\nالكورس ماشاءالله جمع بعض الافكار من 101 و 102 و 201 مثل السيريز والدرفتف والبارشال درفتف و الانتقريشن و الماتركسات وكلش\n\nميجر 1 سهل جدا لا يضيع\nميجر 2 يشد شوية\nالفاينل تبي تميل الى الحفظ غير الفهم.\n\nالهوموركك لا تضيعه حله بيدك وابعد عن المانوال.\nالكورس متراكم فركز من البداية.\n3 الكتاب ممتاز من ناحية وضوح الأمثلة والتمارين.\nقبل الميجر حل كم من اولد اقزام و ان شاءالله تتيسر.\n\nوبالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/30", "user": "Nasalmz", "ts": 1590420390000, "tid": 120616, "pn": 30}}', 1590420390000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1524524-math202', 'stk-user11942', 'MATH 202', 'info', '{"desc": "كورس لطيف وسهل ويكفي إنه ريتن. وموضوعه مختلف عن الكارلكورس يعني راح يكون تغيير بعد ثلاث كورسات كارلكروس ورى بعض. وأسهل من كورسات الكارلكورس الثلاثة وأمتع. الكتاب صعب نوعاً ما ومش واضح مثل كتاب ماث ١٠١ و ١٠٢-٢٠١. حتى دكتوري الخليفي قال لي لو إنه طالب راح يواجه صعوبة بالمذاكرة من الكتاب على الرغم إن الكتاب من أهم المراجع الدراسية في موضوعه عالمياً.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/31", "user": "user11942", "ts": 1596892188000, "tid": 120616, "pn": 31}}', 1596892188000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1526517-math202', 'stk-user11724', 'MATH 202', 'info', '{"desc": "Math202-Term201\n\nفي الاونلاين صارت المادة خيارات وللأسف صارت اصعب لانك ماتاخذ درجات على الخطوات وصارت الدرجات على الجواب النهائي فقط، وعشان كذا المياجر صارت مختلفة عن الفصول السابقة وكثير من الطلاب زعلانين من هذا الشيء، صارت ميجرين ومدتيرم عليها (15+15+15) والافرج على اول اثنين تقريبا 60%. فاذا كانت اونلاين تاكد انك فاهم الكونسبت عشان توصل للجواب النهائي وماتخسر السؤال كامل لانك ماطلعت الناتج النهائي صح، الدكتور مصطفى قاسم له تسجيلات من شرحه على قوقل درايف وكانت ممتازة لفهم الكونسبت انصح بمتابعتها (+ يمديك تسرع المقطع)، الميجر يجيك كله في صفحة وحدة على البلاك بورد 9 اسئلة تحلها في ساعة ونصف، لو يمديك تنتظر الى ما يرجع الوضع طبيعي يكون افضل ولكن ما تضمن انها ترجع رتن اصلا، ممكن يكملون على نفس النظام والله اعلم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/32", "user": "user11724", "ts": 1604555877000, "tid": 120616, "pn": 32}}', 1604555877000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527465-math202', 'stk-aomab', 'MATH 202', 'info', '{"desc": "الكورس سهل وبسيط بس يحتاج تفهم تمام وتدرب يدك على الحل سواء كان الاختبار كتابي او MCQ\n\nللفهم انصحك بشرح الدكتور مصطفى قاسم يعتبر الافضل خاصة لمتيريال الفاينل 👍\n\n+ اسئلة الاولد اقزام مهمة جدا زي اي مادة ماث\n\nوفيه ملف مضغوط فيه ملخصات ان شاء الله تنزل في القروب بداية الترم لأني ما قدرت ارفعها على kfupm resources\n\nوبالتوفيق وفالكم A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-elements-of-differential-equations/120616/33", "user": "AOMAB", "ts": 1609521529000, "tid": 120616, "pn": 33}}', 1609521529000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p634435-math202', 'stk-user4529', 'MATH 202', 'info', '{"desc": "السي بلس يبدأ من 64.25 و ينتهي عند 72\n\nيعني إذا واحد مجموعة 72 ياخذ سي بلس و لو تشاهد الدرجات ستجد الكثير في السي بلس و السبب هو أن رينج السي بلس عالي خاصة أن عادة البي تكون 66 فما فوق أما هذي المرة البي تبدأ من 73 !!!!!!\nحتى البي بلس يبدا من 79 و هو في الغالب يبدأ من 75 أو يصل في بعض الأوقات إلى 72\nو بإمكانك مشاهدة درجات السمسترات الماضية و تشاهد الفرق الذي قد يصل إلى قريدين !!\n\nالان عرفت لماذا دائما تكون الفاينلات صعبة !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-grades/90115/7", "user": "user4529", "ts": 1276648794000, "tid": 90115, "pn": 7}}', 1276648794000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p642365-math202', 'stk-user6860', 'MATH 202', 'info', '{"desc": "كورس سهل وخفيف ، أسهل كورس ماث بين الكورسات الأربعه (لفل ون ولفل تو)\n\nالكورس يتكلم عن المعادلات التفاضلية وطريقة حلها ، الكورس سهل وواضح وشبه مترابط وراح يتكلم عن خمسين طريقة لحل المعادلات التفاضلية…\n\nفي البداية راح تكون الطرق لحل معادلات تفاضلية من الدرجة الأولى… وهذي الميجر ون\n\nوبعدين المعادلات التفاضلية من الدرجة الثانية وفوق… لكن غالباً تجي الثانية ، راح تتعلم طرق للحل وتكون طووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووووويله لكن بسيطه وواضحه ، وبعد كذا تاخذ السيريز واستخدامها في حل المعادلات التفاضلية ، وانجاز اذا كملت مسأله وطلع الحل صح وبعدها تجيك المصفوفات بسيطه وتافهه وهي برضو خطوووووووووووووووووووووووات طووووووووووووووويله للحل\n\nالكورس سهل وخذه في الصيف مع البرمجه مع انوا فيها شوية ضغط لكن مو مره", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/90716/2", "user": "user6860", "ts": 1277252184000, "tid": 90716, "pn": 2}}', 1277252184000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p642785-math202', 'stk-barhomitto', 'MATH 202', 'info', '{"desc": "اهم شي لازم تستوعب وش قاعد تدرس …\nلأنه نوع جديد من الماث اسمه المعادلات التفاضلية مامر عليك قبل كذا\nيعني دالة (function) ومشتقتها، داخل معادلة (equation) …\nالحل (solution) لهذي المعادلة ماراح يكون رقم أو متغير زي ما عرفنا في كورسات الماث السابقة … لا\nراح يكون function جديدة!\n\nباختصار : صعوبتها في انها جديدة عليك… وبعض الطلاب ما قدر يستوعب الفكره الجديده ويفهمها ويطبقها\n\nلو فهمت زبدة المادة وتصنيف المعادلات والطرق المختلفة للحل ومتى تستخدم كل وحده … خلاص done\n\nعلى قول المثل رب سهلةٍ صعبة !!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/90716/6", "user": "Barhomitto", "ts": 1277298472000, "tid": 90716, "pn": 6}}', 1277298472000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1248591-math202', 'stk-ad0rs', 'MATH 202', 'info', '{"desc": "شف هذه درجات اظن 112\na+>/341, a >/319,b+>/306, b >/282, c+>/250, c>/229, d+>/199, d >/169, f <169\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=87104&highlight=%CF%D1%CC%C7%CA+202\n.\nالكلاس وورك من 60 اذا ماكان في اونلاين هومورك\nويكون افرجه 40\nيعني مثلا لو الافرج كان 35 يصير الدكتور يزيد 5 نقاط لجميع الطلاب\n.\nالميجر عليه 100 من 400\nالميجرين عليهم 200 يعني نص الدرجة 50%\nالفاينل عليه 140", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/147461/2", "user": "ad0rs", "ts": 1374755756000, "tid": 147461, "pn": 2}}', 1374755756000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1248638-math202', 'stk-bo5bo5', 'MATH 202', 'info', '{"desc": "^^\nإيوه يخصمون 8.62 للأسف إذا الأفرج 40\n\nالسمستر الماضي كان التوتال أفرج 288 و أفرج الميجرين حول 78 و 80 من 100 والفاينل حول 100 من 140 وهذا توزيع القريدات\n\na+>/362, a >/342,b+>/320, b >/304, c+>/277, c>/242, d+>/212, d >/180, f <180\n\nطبعا دفعتنا ما شاء الله دوافير\n\nطريقة الحساب ما أدري كيف لكن يحسبوه بـ standard deviation", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/147461/4", "user": "Bo5Bo5", "ts": 1374770404000, "tid": 147461, "pn": 4}}', 1374770404000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p454353-math202', 'stk-f.c.b', 'MATH 202', 'info', '{"desc": "الله يكون بعونك لو اني محلك بطلع للتشيرمن واطلب منه انه ما يفصح عن اسمك\n\nالظاهر انه كان موجود الا اذا كنت مشبه على غيره …\n\nالمهم على طاري التغيرات اللي تطلع فجأة\n\nانا داخل الاختبار على ان الوقت 3 ساعات… 180 د (ماث201)\n\nالمهم اني بدأت أحل حتى وصلت للسؤال 10 من 20\n“على الهامش” --> طلبنا من شودري انه يزود عدد الاسئلة قال راح أتكلم مع التشيرمان\nالمهم وإذا بالخبر الصاعقة … minutes left 40\nسألت الدكتور ازهار …وش السالفة ؟؟ … قال الاختبار 150 دقيقة\n\nانا قلت بأتجاهل الموضوع … لأنه مشكلتي ما شفت الــ 150 د اللي في الكوفر بيج\nالشي المضحك انه مو انا اللي طاح في هالملقب … كل اللي راكبين الباص اللي اعرفهم واللي ما اعرفهم\nشكوا من نفس المشكلة !!!!\n\nولا ننسى ميجر 2 … نفس الحركة 100 د …علما أن ميجر 1 120 د\n\nولا أحد يجيني ويقلي ليش ما تشوف الوقت وتتأكد\nانا من يوم دخلت الجامعة …كل كورسات الماث من الاوريا حتى 102 المياجر ساعتين والفاينال 3!!!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/77082/7", "user": "F.C.B", "ts": 1252028935000, "tid": 77082, "pn": 7}}', 1252028935000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p454376-math202', 'stk-f_ahad', 'MATH 202', 'info', '{"desc": "يا اخوان\n\nوالله عيب الي سووه فينا اليوم قسم الماث وانا بعد سمعت عن سالفت ال ٢٠١ بعد\n\nلكن الحين ما في شي اسمه ان هذي الطريقه الي اختبرنا فيها اليوم تكون طريقه مدروسه\nيا خي برنس مان انت اخذت ٢٠٢ ؟؟\nاولا ٢٠٢ عشان تحل مسأله وحده لازم تكتبها بخطواتها وفيه بعض المسائل تختبر قدرتك على التكامل\nوبعدها ممكن تنحل بأكثر من قانون يعني الطالب الي يتعب ويحل بالقاعده السهله والبسيطه ويغلط غلط بسيط مثلا قسمه\nعلامه بنص المسأله\nتبي تشيل عليه كل الدرجه حرام والله حرام\n\nلا وفي سؤال ثاني تجيب جوابين لمعادله ولما تجيبهم لهم قاعده تعوض فيها الجوابين\nطيب لو واحد خطأ في تعويضه في القاعده رغم انه جاوب الحل الصحيح ( الجوابين ) وش يسوي تطير الدرجه\n\nصراحه لاهي مدروسه ولاشي\nهم يمكن درسو كيف يقدرون يصححون بسرعه ويطلعون الدرجات عشان الطالب ياخذ القريد حقه بسرعه\n\nالله يعين بس.\nوعلى فكره الشير مان كان موجود اليوم\n\nعمركم شفتم ٢٠٢ اختبار فاينل مو ريتنق شلون تدخل الراس هذي شلووووووووووووووووووووون\nالله يخلف على جامعة الفهد\n\nاجل الدراسه الحين عشان الفهم ولا عشان القريد انا ودي افهم\nبالاختبار الي سووه اليوم كان المفروض يقولون يا شباب لاتفهمون واجد ولا تحبون الماده لاكن ركزو على الدرجه\nلازم تاخذون درجات عشان لما تتخرجون تعلقونها ببيوتكم وتقولون انكم متخرجين من البترول وتقعدون بالبيت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/77082/10", "user": "F_ahad", "ts": 1252033278000, "tid": 77082, "pn": 10}}', 1252033278000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p454497-math202', 'stk-user2781', 'MATH 202', 'info', '{"desc": "يا عسى الافرج ينخفس ع الروس 😦\n\nكلمت الدكتور قبل الاختبار وقالي المطلوب الفاينل آنسر فقط\n\nقلت له ظلم حرام شلون دكتور؟\n\nيقولي، الاختبار الخميس والسبت العصر الريجيسترار يبي الدرجات ولازم قبل موعد التسليم بيوم تكون فترة اعتراض ع الدرجات ،،\nوما فيه وقت ابد\n\nوانا احتاج ع الاقل اسبوع عشان اصحح الاوراق … إلخ\n\nوالاختيارات ما تنفع، لأن الكورس ديفرينشيات اكويشن، سهله تعوض ويطع لك الحل\n\nظلم 😦\n\nقلت له الريجيسترار كلمه\n\nيقولي الريجسترار تكلمه ما فيه فايدة ما يسمع ابد\n\nالميجر تو ابي اغير نص ساعة سوا لي زحمه طويلة عريضه وبالغصب غيرت\n\nعاد كيف الفاينل؟\n\nالله يعين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/77082/21", "user": "user2781", "ts": 1252072290000, "tid": 77082, "pn": 21}}', 1252072290000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p851288-math202', 'stk-che-240', 'MATH 202', 'info', '{"desc": "* السلام عليكم ورحمة الله وبركاته *\n\nبصراحة انا احد طلاب هذا الكورس و حالي حال الطلاب الباقين ,\n\nسمعت كثير , قريت كثير هنا عن الافريج وان الافريج عالي مرة وانه شي من الخيال , 😲\n\nخلنا نترك العاطفه والقريدات ع جنب :sneezing_face:\nونتكلم بالمنطق شوي ( طبعا المنطق اللي نعيشه بهالجامعه) 😐\n\nبمسكها نقطه نقطه ( وتذكروا ان هالكلام مو رأيي انا , هذا الشي اللي يقوله المنطق و الارقام) 🙄\n\n------------------------------------------------------------------------------------------\n\n*** نرجع للسمستر الماضي , سمستر 101 > كل الطلاب قالوا الافريج عالي وبصراحة دورت توزيع الدرجات ومالقيت , لكن اللي سمعته ان الـ A+ تبدا من 369 ( ويعتبر شي مرررة عالي)(( لكن لما تجي تقارن , قارن ب مادة 202 في السمستر الثاني , لانها مادة رئيسيه بهالوقت , مو بالسمستر الاول))\n\n================================================\n\nنرجع لـ سمستر 092 >> واتوقع كل الطلاب يقدرون يشوفونه ع الموقع … ودرجاته كانت بالتوزيع الاتي :\n\nCRITERIA:\nA+>/368\nA>/342\nB+>/318\nB>/291\nC+>/257\nC>/226\nD+>/202\nD>/178\nF<178\n\nهذا الافريج قريب نوعا ما لـ افرج السمستر هذا /\n\n(خالد القرني 07) قال انه اخذ 260 و اخذ C+ و مع افريج 092 نفس القريد\n(realistic) قال انه اخذ 268 و اخذ c+ ومع افريج 092 نفس القريد\n(انت ويش دراك) اخذ 235 و اخذ d+ ومع افريج 092 ياخذ c\n(وائل عادل) اخذ 278 واخذ c+ ومع افريج 092 نفس القريد\nوائل عادل قال ان خويه اخذ 281 واخذ c+ مع افريج 092 نفس القريد\n(break) اخذ 291 و c+ ومع افريج 092 في بدايه b ( الـ b تبدا من 291)\n(عالي الطموح) اخذ 243 و اخذ c ومع افريج 092 نفس القريد\n(صبعبلي) اخذ 247 واخذ c ومع افريج 092 نفس القريد\n(قلم بلا حدود) اخذ 292 و اخذ C+ ومع افريج 092 ياخذ B ( الـ B تبدا من 291 )\n\n=======================\n\nبشكل عام , بين سمستر 102 و 092\n\nافريج الـ A+ نزل\nافريج الـ A نزل\nافريج الـ B+ تقريبا ثابت\nافريج الـ B تقريبا ثابت\nافريج الـ C+ تقريبا ثابت\nافريج الـ C تقريبا ثابت\nافريج الـ D+ مرتفع\nافريج الـ D ( بصراحة ماادري بس هذا القريد مايتغير اكثر من 2 الى 3 بالكثير)\n\n==========================\n\nنرجع لـ سمستر 082 ( الدرجات في الموقع من 200 , انا ضربت كل درجة في 2 عشان تكون من 400)\n\nCRITERIA:\nA+>/368\nA>/342\nB+>/318\nB>/294\nC+>/260\nC>/228\nD+>/206\nD>/180\n\nوهذا الافريج برضو قريب من افريجنا:\n\n(خالد القرني 07) قال انه اخذ 260 و اخذ C+ و مع افريج 082 نفس القريد\n(realistic) قال انه اخذ 268 و اخذ c+ ومع افريج 082 نفس القريد\n(انت ويش دراك) اخذ 235 و اخذ d+ ومع افريج 082 ياخذ c\n(وائل عادل) اخذ 278 واخذ c+ ومع افريج 082 نفس القريد\nوائل عادل قال ان خويه اخذ 281 واخذ c+ مع افريج 082 نفس القريد\n(break) اخذ 291 و c+ ومع افريج 082ياخذ نفس القريد\n(عالي الطموح) اخذ 243 و اخذ c ومع افريج 082 نفس القريد\n(صبعبلي) اخذ 247 واخذ c ومع افريج 082 نفس القريد\n(قلم بلا حدود) اخذ 292 و اخذ C+ ومع افريج 082 ياخذ نفس القريد\n\n======================================\n\nبشكل عام , بين سمستر 102 و 082\nافريج الـ A+ نزل\nافريج الـ A نزل\nافريج الـ B+ تقريبا ثابت\nافريج الـ B تقريبا ثابت\nافريج الـ C+ تقريبا ثابت\nافريج الـ C تقريبا ثابت\nافريج الـ D+ مرتفع\nافريج الـ D ( بصراحة ماادري بس هذا القريد مايتغير اكثر من 2 الى 3 بالكثير)\n\n======================================\n\nبشكل عام الافريج واحد بين سمسترنا والسمسترات الماضيه ,\n\nطلاب الـ A والـ A+ حصلوا افضل من المتوقع\nطلاب الـ B+…B…C+…C… ماتغير عليهم شي\nطلاب الـ D+ حصلوا اقل من المتوقع\nطلاب الـ D بصراحة ما ادري\n\nيعني افريج الماده بشكل عام عالي ,\nما اشوف ان فيه مشكله بهالسمستر لان هالشي نعرفه وماهو جديد 😐\n\nاتمنى ان نحترم الارآء , مع العلم ان كل شي قلته ماهو راي , وانما ارقام وتفاصيل 🌹\n\nو لكم التوفيق في باقي المواد 🌹 ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/grade-math-202/108187/46", "user": "CHE-240", "ts": 1307866839000, "tid": 108187, "pn": 46}}', 1307866839000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p853820-math202', 'stk-user4774', 'MATH 202', 'info', '{"desc": "انا نفس حالتك ناقصني 4\\400 عالقريد الي بعده\n\nرحت للدكتور قالي اذا درجت الفاينل حقتك في الرينج حق القريد الي فوق يمكن يقدر يسويلك شيء غير كذا ما يقدر\n\nيعني مثلا انت جايب 276\\400 وفرضا الـc+ من 280\\400\n\nوجبت في الفاينل مثلا 105\\144 تطلع درجت الفاينل من 400 تطلع لك 292 وهذه الدرجة داخلة في رينج ال c+ فالبتالي تستحق الـ اب قريد\n\nاما اذا جبت 90\\144 مثلا تطلع 250\\400 فما يعطيك اب قريد لان درجة الفاينل اقل من الدرجة الي تعطيك c+ حتى لو باقيلك 1\\400\n\nهذا الكلام حسب دكتوري محمد يوسف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/grade-math-202/108187/89", "user": "user4774", "ts": 1308138487000, "tid": 108187, "pn": 89}}', 1308138487000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p63768-math202', 'stk-user439', 'MATH 202', 'info', '{"desc": "math-202 :- موضوعه Diffrential Equations\n\nالماده بصيغة العموم سهلة ممتنعة لإعتمادها على ما قبلها اعتماد كبير وخاصه في حل التكاملات في math-102\n\nالمنهج قصير 5-6 شباتر بالكثير واجزاء كثيره من الشباتر محذوفه\n\nافضل مدرس يعطي الماده هو الدكتور/شعنان\n\nويتبعه بالفضل\n\nالدكتور/ الجبيلي\n\nالدكتور/ AZAD", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/42318/2", "user": "user439", "ts": 1099820481000, "tid": 42318, "pn": 2}}', 1099820481000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p65462-math202', 'stk-top_secret', 'MATH 202', 'info', '{"desc": "شوف اذا كنت تبي نصيحتي\nانصحك انك تاخذها مع سرحان … صحيح انه شديد في الحضور و الهوموركات بس يعجبك في الاسئله انا اخذتها معاه في الصيف والحمدلله جبت معاه +B بس اياك تغيب اذا مره مره غياب واحد و الواجبات سلمها اضمن انك تجيب معاه درجه ترضيك … والماده بشكل عام سهله والكتاب يغنيك عن نوت المدرس ( طبعا هو ما فيه نوت معاه تقريبا لانه يكتب بشكل ماهو مرتب , يعني تلقها يكتب في مكان في السبوره والا هو في الطرف الثاني و يمسح كثير )\nطولت عليك الكلام من النهايه سلم الواجبات كلها و احضر وراح تدعيلي\n\nعلى فكره الافرج كان معاه في الصيف 75 -80 بس ما يلتزم فيه\n\nاتمنى اني افدتك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/42318/6", "user": "TOP_SECRET", "ts": 1102543618000, "tid": 42318, "pn": 6}}', 1102543618000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1433968-math202', 'stk-the_aviator', 'MATH 202', 'info', '{"desc": "وعليكم السلام .\nلا تنزل عند تاتار ، تصحيحه سيء جداااا .\nالمادة سهلة ، كلها سلف ستدي فما يبغالها دكتور شريح والكتاب شرحه واضح .\nنزل عند دكتور تصحيحه زين .\nأفضل الموجودين في موقع المسجل :\n1- عثمان عشّي\n2- يعقوب شحادة\nوفيه عبد السلام ميموني ، بس ما أدري كيف تصحيحه.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math202/170880/3", "user": "THE_AVIATOR", "ts": 1448038361000, "tid": 170880, "pn": 3}}', 1448038361000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p43278-math202', 'stk-the_maestro', 'MATH 202', 'info', '{"desc": "East Or West DR. BILALA CHANANE Is The Best\n\nأخوي شوف لا يمين و لا شمال … بلال شنعان جدا جدا جدا ممتاز\n\nأنا أخذت عنده ماث 202 … و إليك التالي\n\n1- ما عنده شي اسمه حضور … يعني الرجل ما يعرف شي اسمه DN\n\n2- النوت حقه جدا لطيف بصراحة … و الرجل متمكن من المادة\n\n3- عنده 5% للسيرة و السلوك … يعني … 5% في جيبك يا ابو الشباب… طالما انه ما ياخذ حضور … يعني … ال 5% ما يحكمها حضورك او غياب و انما هي هدية في جيبك\n\n4- اسئلته في الكويزات و المياجر … معتدلة … فيها شوية صعوبة\n\nلكن\n\nلكن\n\nلكن\n\nخذ مثلا السكشن اللي صرت فيه انا\n\nالميجر الاول اخذت 48 من 100\nالميجر الثاني اخذت 30 من 100\nالكويزات اخذت 3 من 10\n\nطلبنا منه ميجر ثالث حتى نرفع درجاتنا\n\nالرجل بصراحة ما عاند و لا خالف … طلب بس ان يكون في عدد معقول يريد هذا الميجر\n\nالمهم اخذنا الميجر … و كان جدا جدا لطيف بصراحة\n\nالمهم في النهاية اخذت C", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/31488/6", "user": "The_Maestro", "ts": 1076518098000, "tid": 31488, "pn": 6}}', 1076518098000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534407-math202', 'stk-ahmed1', 'MATH 202', 'info', '{"desc": "Math 202 - Term 212\n\nالتحضير : ورقة تمر على الكلاس وما يدقق على الحضور واجد والتأخير لو تجي اخر دقيقة تاخذ الورقة وتحضر نفسك، في نهاية الترم بعد سوا حركة رهيبة انه ما قام يحضر تقريبا اخر اسبوعين و حذف كل الغيابات ما قصر.\n\nطريقة الشرح : يشرح من السلايدات اللي هو مسويها و اشوفها حلوة الصراحة توصل لك الكونسبت بشكل مضبوط بس فيها عيب انه مافيها الا كم سؤال اولد مب واجد.\n\nالكويزات : كويزاته حيل سهلة وبتكلم عن الموضوع زيادة.\n\nالصوت: واضح جدا ولغته ممتازة.\n\nالتصحيح: رهيب ويعطيك فوق حقك وما يستقعد ويحاول يساعدك باللي يقدر عليه.\n\nإضافات: الدكتور طيب وراعي مزح في الكلاس ويعرف الطلاب بأساميهم حتى وهو ما يحضر بالاسماء بس يسأل احيانا ويسألك عن اسمك وكذا واحيانا يخلينا نحل سؤال في بداية الكلاس بدون ما يشرح وكذا و اشوفها حركة حلوة، و الصراحة فهمت الكونسبت معاه مضبوط بس طبعا لازم تشتغل على نفسك في البيت.\nبس فيه عيب يقهر، الدكتور من كثر ماهو طيب ويبي مصلحة طلابه صار الموضوع عكسي على الاقل بالنسبة لي، شلون؟ بعد اول كويز وبعد ما شاف انه الافرج نازل راح سأل الطلاب عن رايهم وشنو يسوي عشان تتحسن الدرجات، طبعا الاقتراحات كانت تقهر وتهضم جهد الطلاب الممتازين و تفيد الطلاب الاقل مستوى، اللي سواه انه عطانا 4 كويزات و وواجبين سهلة، وطبعا معروف الواجبات عندك السلوشن مانوال، و اخذ افضل 4 من الاشياء ذليه وطبعا افرج الواجبات 90 و الكويزات اعلى واحد 74، فلك ان تتخيل الوضع الكل نقص وحتى اللي يستاهل الكلاس وورك فل، نقصنا 4 بوينتس في النهاية و اقل سكشن نقص عنده نقص 2 بوينتس. انا كان المفروض اخذ فل في الكلاس وورك حتى لو اخذ كل شي لانه في النهاية الافرج بيرفعنا بس عوافي، اذا ما عدل من السلبية ذي لا تنزل عنده خصوصا الكورسات السهلة 202 و 208 لانه البوينت الوحدة تفرق.\n\nالتقييم النهائي له: A\n\nعموما اشوف الدكتور رهيب ومستغرب انه للحين مب معروف واجد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kareem-elgindy/178380/8", "user": "Ahmed1", "ts": 1653366314000, "tid": 178380, "pn": 8}}', 1653366314000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450529-math202', 'stk-ahmed_sh', 'MATH 202', 'info', '{"desc": "حياك الله اخوي\nللاسف لا يوجد عندي حلول الكتاب المرفق\nالمنهج المستخدم في البترول هو ماث ظ¢ظ*ظ¢ والكتاب هو A first course in DE by Dennis Zill واللي موجود هنا بالرابط مع الحلول والملخصات بالاضافة الى الاختبارات القديمة للكورس - Math202.zip - Google Drive", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/173453/6", "user": "AHMED_SH", "ts": 1464337419000, "tid": 173453, "pn": 6}}', 1464337419000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1222846-math202', 'stk-user6441', 'MATH 202', 'info', '{"desc": "^^\n\n😦\n\n--------\n\nالكورس الثاني che453\nMathematical Methods in Chemical Engineering\n\nعند الدكتور بينوس\n\nالكورس خفيف وحليو\n\nعباره عن اعاده لشوية اجزاء من الكورسين math202 & cise301\nوتاخذوا عليها تطبيقات لبعض مسائل الكيميكال\n\nفي البدايه بتتعلموا شلون تحلوا الديفرنشيال ايكويشنز(( ODE و PDE )) \"ماث202 \" وبعدين ابليكيشنز في التخصص >>> الميجر الاول والثاني\n\nوبعدها تنتقلوا للنيوميريكال ميثود >>> هنا تقريبا نفس كورس cise301 ولكن بشكل مصغر\n\nكيف تحلوا المعادلات نيوميريكالي بستخدام نيوتن ميثود , رنج كاتا ميثود , شووتنق ميثود … الخ\n\nوبرضوه راح تتعلموا كيف تستخدموا برنامج mathematica >> يوديكم لللاب من فترة لفترة وتطبقوا عالبرنامج\n\n----\n\nالكورس عباره عن ميجرين و فاينال\nالكلاس وورك عالحضور والهومووركات و ما كان فيه كويزات\n\nالافرج B الى B+ على كلام الدكتور\n\nاسئلة المياجر سهله والفل مارك الكل يقدر يجيبها\n\n----\n\nالدكتور\n\nمسهل علينا الكورس بشكل كبير\nالتحضير >> نص الكلاس وبشكل يومي تقريباً\n\nتصحيحه مرره سيئ\n\nمياجره سهله و هومووركاته قليله نوعاً ما “” 6 الى 7 هومووركات “”\n\n-----\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/143746/11", "user": "user6441", "ts": 1368663709000, "tid": 143746, "pn": 11}}', 1368663709000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1166758-math202', 'stk-ahmed_alhntoshi', 'MATH 202', 'info', '{"desc": "math 202 متوسط الى سهل لا تضيع القريد به\n\nاذا تقصد بالــ 270 ، 207 مادة تحتاج متابعة أول بأول الميجر الأول متاترياله سهل الى متوسط ( بناء على متابعتك ) راح تدرس بشكل مركّز partial fraction , state variables & integration\n\nمتوسطة الى صعبة\n\n390\n\nمادة حلــوة فلا تضيع القريد فيها ، نفس الكلام بردي الي فوق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/134666/143", "user": "Ahmed_Alhntoshi", "ts": 1358706779000, "tid": 134666, "pn": 143}}', 1358706779000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p951625-math202', 'stk-user6099', 'MATH 202', 'srcU', '{"html": "اللي يقدر يحل الأسئلة هذه أو بعضها يحطها هنا الله لا يهينكم<br><br>​<span data-fid=\"stk-f951625-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f951625-0": {"name": "m202-111-q3 a.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/116859/1", "user": "user6099", "ts": 1324566740000, "tid": 116859, "pn": 1}}', 1324566740000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p966517-math202', 'stk-user8301', 'MATH 202', 'srcP', '{"html": "في الرفقات<br><br>​<span data-fid=\"stk-f966517-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f966517-0": {"name": "Solution-Math202-111-Final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a2e5a34ca6274f35cc848fd7e7a1837d65ed574ec3bd70010ee9f79219ad5ec4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202/118133/5", "user": "user8301", "ts": 1326470479000, "tid": 118133, "pn": 5}}', 1326470479000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
