INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p417263-math202', 'stk-user1811', 'MATH 202', 'srcP', '{"html": "بالتوفيق يا شباب<br>🌹<br><br>​<span data-fid=\"stk-f417263-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f417263-0": {"name": "202 final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e348cb2d0b61f2cf114fc8d30bfdcb210c7b65be472693ff2712f915d2e02586"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-202-final-exam-sol/74340/1", "user": "user1811", "ts": 1245576518000, "tid": 74340, "pn": 1}}', 1245576518000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
