INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p822116-math202', 'stk-user6130', 'MATH 202', 'srcP', '{"html": "بالتوفيق يا شباب 🌹 .<br>تحميل الملف MATH202_083_01_E1.pdf من هنا<br>الملف الأول الميجر مع الإجابة أما الثاني فبدون إجابة.<br><br>​<span data-fid=\"stk-f822116-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f822116-0": {"name": "MATH202_083_02_E1.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/202-083/105467/1", "user": "user6130", "ts": 1300837785000, "tid": 105467, "pn": 1}}', 1300837785000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p805375-math202', 'stk-_0014', 'MATH 202', 'srcU', '{"html": "تفضل في المرفقات<br><br>بالتوووفيق<br><br>​<span data-fid=\"stk-f805375-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f805375-0": {"name": "MATH202.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e21c2b9d9e22d12f6cc04dc9219a3769c18f1832fc6b6ac7601e78fee8f66b08"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/104087/8", "user": "_0014", "ts": 1299196910000, "tid": 104087, "pn": 8}}', 1299196910000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-math202', 'stk-user11372', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68348", "n": "Dr. Abdallah Laradji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math202 - Term 202 اونلاين\n\nالتحضير : الدكتور يحضر بالسيريال نمبر نهاية الكلاس وماراح ينادي اسمك طول الكلاس ابدا\n\nطريقة الشرح : يشرح من نوتات خاصة فيه , صراحة ماشوف شرحه ممتاز ولا سيئ مره يعني لو مركز معاه 100% بتفهم لكن مو مره اللي يخليك مستوعب الدرس\n\nالكويزات : اووه يالكويزات وما ادراك ما الكويزات جيب شاهي واقرا\nهذي اكثر شي صراحة يتعبني مع الدكتور اللي هي الكويزات , طبعا الكويزات مستحيل تكون معاه الصباح مستحيل دايم بالليل\nوحتى لو كلمناه يقول ماقدر وغصب تصير بالليل\nطبعا الكويز مدته نص ساعة فقط مفروض ونمشي طبعا الكويز ريتن\nلكن !!! وحط الف خط تحت لكن\nالكويز ياخذ من ساعة ونص الى ساعتين ليه ؟\nلان الدكتور يطلب في الكويز يشيك البطاقة الجامعية لكل طالب ! طبعا اوكيه هذا شي نقول عادي وياخذ 20 دقيقة\nبعد الكويز يطلب من كل طالب ترفع اوراقك قدام الكام امام الطلاب وياخذ سكرين شوت على كل ورقة ! هذي العملية تاخذ حول 30 دقيقة\nتخيل كل طالب يحل 3 اسئلة ب 3 اوراق وعدد الطلاب 30 ! يعني بيصور الدكتور تقريبا 90 ورقة من الطلاب !\nوبعد ماياخذ السكرين شوت يقولك يالله سوي سكان وارفع الاوراق بلاك بورد\nطبعا نقطة مهمة : الدكتور يطلب كل كويز 3 اجهزة (الكمبيوتر حقك اللي بتختبر فيه + الجوال للكام + جهاز اخر تسوي فيه سكان)\nممنوع معه تستخدم الجوال للكام والسكان بنفس الوقت !!!\nطبعا كلمناه كثير ويقول هذا policy وهذا شي من الجامعة لكن كنت اشوف محد من دكاترة الجامعة يسوي هذا الشيء\n\nالمياجر: كان ميد ترم واحد وخيارات وصراحة من وجهة نظري المادة ماتصلح خيارات ابدا !!! المادة ريتن وطبعا جميع سنوات الحضوري كانت حضوري باسثناء ترمين اتوقع\nتغيرت ورجعت الاختبارات ريتن . ليه الريتن احسن ؟ لان الاجابات للاسئلة طويلة وفيها حساب واشياء قديمة من math002 و math102 سيريس ومصفوفات واشياء يبغالك تحل 10 دقايق وبعدين تغلط بإشارة ! صعب\n\nالفاينلات : نفس سالفة الميد صارت خيارات للاسف\n\nالقريد النهائي: هذا تقييمي للدكتور ومو قريدي , اعطي الدكتور C+\n\nالصوت: واضح الصوت لهجة اردنية او سورية او لبنانية\n\nإضافات : الدكتور ممنوع معاه ريكورد المحاضرات مره مايرضى", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530367-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-laradji/68348/49", "user": "user11372", "ts": 1622888233000, "tid": 68348, "pn": 49}}]}', 1622888233000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3628-math202', 'stk-user3628', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا درست معاه math 202\n\nالتعامل : راقي جددددددددددا وحبييييييب لابعد درجة\n\nالشرح : حلو مرة وخصوصا انه يكتب نوت على السبورة وبشكل تفصييييلي يعني حتى لو ما فهمت شغله ممكن ترجع للنوت بعدين\n\nالقريد: يعطيك حقك\n\nاختباراته جدا معقولة وممكن تقول اقرب للسهولة\n\nطبعا كان يقول ان تخصصك ولعبته هي الmath 201\nوهو منزلها الترم الجاي\n\nالقريد النهائي a", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p400163-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/3", "user": "user3628", "ts": 1241809704000, "tid": 68366, "pn": 3}}]}', 1241809704000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cpc_2015-math202', 'stk-cpc_2015', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68373", "n": "Dr. Abdeslam Mimouni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 - term 162\n\nالتحضير : غالبا ما يحضر إلا ما ندر\n\nطريقة الشرح : يكتب التعريف من ثم يشرح المفهوم من ثم يعطي مثال سهل بعده متوسط بعدين يعطي أمثلة من الأولد إقزامز\n\nالكويزات : متوسطة إلى سهلة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\nإضافات : الدكتور شريح ويوصل المعلومة بشكل ممتاز، الي يكتبه ع السبورة شي اسطوري ، لو تكتب وراه و تذاكر من اللي كاتبه راح تلاقيه أفضل من أي نوته موجودة ، تذاكرها و على طول تروح لأولد إقزامز ، و إذا مالك خلق صور وراه\n\nملاحظة : الدكتور أحيانا يعصب على بعض الطلاب و خصوصا في بداية السمستر ، لكن الرجل محترم وحبيب و له خبرة عالية في التدريس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473650-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdeslam-mimouni/68373/43", "user": "CPC_2015", "ts": 1495483918000, "tid": 68373, "pn": 43}}]}', 1495483918000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammedj-math202', 'stk-mohammedj', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 Term172\n\nالتحضير: بداية المحاضرة ينادي بالسيريال ويخصم نص بوينت على التأخير( 5 دقائق بعد ما تبدأ المحاضرة) و بوينت على الغياب, لكن يبدأ الخصم مع الغياب الثالث .\nطريقة الشرح: شرح سيء مره, خط غير مفهوم, وملخبط بكلامه.\nالكويزات: تجي(غالبا) أسئلة نسخ لصق من أمثلة النوته حقته.\nالتصحيح: تصحيحه جبار دفني بقوة.\nالقريد النهائي: B+\nالصوت: واضح بس لهجه هندية, مرات ما افهم وش يقول.\nأضافات:\n-عنده نوته جباره, كنت اذاكر منها فقط, ماا احل لا اولد اقزام ولا هوموركات ولا شيء, بس احل الأمثلة اللي فيها والحمدلله طلعت بقريد كويس.\n-هو شرحه خايس, بس يسمح تستخدم الجوال او تنام او اي حاجه.\nرابط حق ماث202 وفيه نوت الدكتور:\nMATH202 - Google Drive", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492614-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/42", "user": "mohammedj", "ts": 1526573907000, "tid": 68375, "pn": 42}}]}', 1526573907000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khmg-math202', 'stk-khmg', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term 182-math202\n\nالتحضير :يحضر بعد خمس دقايق من بداية الكلاس والغياب عليه خصم +(ما يعطي اوف بدل المياجر)\nطريقة الشرح :يشرح من نوتاته ,النوتات كويسه بس الدكتور شرحه سيئ وخطه مب واضح وما يشرح الا والنوته في يده لو يجي بدون النوته ما يعرف وش يقول.\nالكويزات : يجيب اشياء قريبه من الي في نوتاته ومرات نفسها بالأرقام بشكل عام كوزاته من سهله الى متوسطه\nالتصحيح:نظامه فالتصحيح ينقصك في سؤال ويزيدك في واحد ثاني يعني ما كأنه سوا شي ويدقق اذا ما كتبت كلام وكان مكتوب فالسلوشن يخصم كثير عليها مقارنتا بالدكاتره الباقين يعتبر عادي الى سيئ فالتصحيح\nالقريد النهائي:D+\nالصوت:واضح\nإضافات :\nالدكتور كان يسمح باستخدام الجوال بس فوسط الترم بدا يدقق على الي يستخدمونه\nبشكل عام ما انصح فيه الا اذا انحديت عليه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508944-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/43", "user": "KHMG", "ts": 1556117727000, "tid": 68375, "pn": 43}}]}', 1556117727000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-math202', 'stk-khdsa2022', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68381", "n": "Dr. Jaafar Al-Mutawa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم - منقول عبر واتساب\n\nاسم المدرس : JAAFAR AL-MUTAWA\nالمادة : MATH 202\nالترم: 183\n\nالتحضير : في آخر الكلاس ورقة تمر على الطلاب, ما يحاسب على التأخير, حتى لو دخلت بعد 20 دقيقة ما يقول لك شيء, ولأحيان كثيرة ينسى يحضر. في طلاب قالوا أنه يعطي بونص للطلاب الي ما يغيبوا كثير بس هذا ما حصل عندنا لأنه أفرجنا أصلا كان مرة مرتفع\nطريقة الشرح : يبني لك المفهوم حبة حبة, ما يستخدم سلايدات يشرح على السبورة ويتقبل الأسئلة بصدر رحب, شخصيا أحببت طريقة شرحه جدا\nالكويزات : في البداية أهطانا كويزات سهلة, بس لما أفرجنا ارتفع شد علينا شوية\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : الكورس اختباراته written والدكتور تصحيحه أنا أشوفه حقاني يعني مو ذاك المتساهل, ولا أنه ياخذ حقك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513685-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jaafar-al-mutawa/68381/60", "user": "Khdsa2022", "ts": 1565784115000, "tid": 68381, "pn": 60}}, {"id": "stk-dr-m68403", "n": "Dr. Mustapha Kassem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "by whats app\nاسم الدكتور : مصطفى قاسم\nالمادة: MATH202\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : الدكتور يحضر يوميا بنهاية الكلاس والتأخير عنده جدا عادي لو تجي بعد نص ساعة من بداية الكلاس يسألك بس وش كنت تسوي بعدين يقول لك خش ويحضرك ما يحطك ليت بالعربي اسطورة بالتحضير\nطريقة الشرح : عنده نوتات خاصة فيه، اجدها احيانا مب احسن مصدر للمذاكرة ولكن مفيدة.\nالكويزات : كوزاته جلد ودائما الافرج بالحضيض ويخليك تذاكر غصب وبالنهاية يرفع الكل\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: يوصلك صوته وينفهم عليه لو كنت تبي تركز\nإضافات : الدكتور تصحيحه اسطر شي بالتاريخ، بخصوص ان المادة ريتن اذكر اول ميجر كان الافرج العام ٧٣ او شي وافرج سكشني كان ٨١، الدكتور تصحيحه بطططل المهم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518762-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustapha-kassem/68403/41", "user": "Khdsa2022", "ts": 1578209992000, "tid": 68403, "pn": 41}}, {"id": "stk-dr-f152770", "n": "Dr. Asad Muhammad Butt", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سم الدكتور : mohammed butt\nالمادة:MTH202\nBY WHATS APP\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :ورقه تمر على الطلاب وتحضر نفسك ويعد الطلاب عشان يتأكد اذا فيه احد محضر خويه\nطريقة الشرح :يحاول يفهم أمثله الكتاب ويرجع يشرحها لنا\nالكويزات :من نفس اسئلة الكتاب وغالبا لو تحل الواجب بتحلها\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:C\nالصوت:مسموع\nإضافات :دكتور حافظ ماهو فاهم انا اتكلم عن مادة MATH202 وهذا كان اول سمستر له ودكتور تصحيحه ظالم في كل المتجر تحت الافرج العام بأكثر من ٩ درجات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518791-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/asad-muhammad-butt/152770/2", "user": "Khdsa2022", "ts": 1578285465000, "tid": 152770, "pn": 2}}, {"id": "stk-dr-m176965", "n": "Dr. Jae-Chean Joo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "by whatsapp\nاسم الدكتور : Joo jae chean\nالمادة: math_202\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : بداية الكورس ماكان يحضر واهو قال لنا اصلا ما بحضر لاكن لازم تحضرون الشعب سحب عليه وماصار يحضر كثير في الكلاس ٣ او ٤ بعدها صار يحضر الى نهاية السمستر\nطريقة الشرح :\nشرحه كله عالسبورة وبعد ما يخلص الشرح يحل كم مثال من الاولد اقزامز او الكتاب. والي تجاهله الكثير انه شرحه في math 202 ممتاز جدا اشوفه ويوصل المعلومه بشكل حلو اشوفه\nالكويزات : متوسطه الى سهله\nالمياجر: كومن وتصحيحه بالنسبه لي اشوفه جميل لاكن اشوف كثير يذمون تصحيحه لاكن انا اشوفه ساعدني كثير\nالفاينلات : كومن\nالقريد النهائي: b\nالصوت: هو كوري والاكسنت حقه مضرووب وبعض الاحيان تحس انه يسحب ع الانقلش ويتكلم كوري لاكن في اغلب الاحيان تفهم عليه\nإضافات :\nبالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518826-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jae-chean-joo/176965/4", "user": "Khdsa2022", "ts": 1578293458000, "tid": 176965, "pn": 4}}]}', 1565784115000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_ahmed3-math202', 'stk-_ahmed3', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 - term 192\n\nالتحضير :\nيحضر نهاية الكلاس ولا يسجل تأخير على احد.\n\nطريقة الشرح :\nيشرح عن طريق السلايدات ، عنده تابليت يشبكه ع البروجكتر و يحل المسائل ف نفس السلايدات بالقلم مال التابليت.\n\nالكويزات :\nهذا الترم اخذنا نصه دراسه عاديه ونصه اونلاين … في الوضع العادي كانت كويزاته متوسطه مايله للسهوله و ف الاونلاين كانوا معظمهم صعبين ، عطانا ٦ وحذف اسوأ اثنين.\n\nالميجر :\nكومون\n\nالقريد النهائي :\nA\n\nالصوت :\nمنخفض ولكن مسموع.\n\nإضافات :\n١- تصحيح الدكتور للمياجر والكويزات اسطوري، يعطي الطالب زياده عن حقه بكثيير.\n٢- الدكتور متساعد جدا من ناحية تسليم الهومووركات، كلمه بس اذا جاء الددلاين وانت ماخلصته ويقولك عادي تسلمه الكلاس الجاي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521815-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/42", "user": "_Ahmed3", "ts": 1588769405000, "tid": 68383, "pn": 42}}]}', 1588769405000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_lion013-math202', 'stk-the_lion013', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202\nTerm 151\n\nالتحضير :\n\nكل كلاس واوحيانا يسحب على التحضير\nوالغى لنا تقريبا اربع كلاسات نهاية السمستر وكثير من كلاسات نهاية السمستر ماحضر فيهم\n\nطريقة الشرح :\n\nيشرح لك بطريقة واضحة ومفهومة ويعززها بأمثلة من الكتاب (يعني تطلع فااهم من الكلاس) لكن اذا السوال يحتاج مهارة من مهارات ماث الاوريا او ظ،ظ*ظ¢ يذكرك بالطريقة والبروبرتيز لكن مايفصل لك المثال لان راح يضيع الوقت وهو يشرح بروبرتيز حق ماث 102 مثلا وهو لسه ماعطاك فكرة السوال من ماث 202\n\nالكويزات :\nظ¤ كويزات تقريبا سهله مائلة للمتوسط واغلب الاحيان يحب يجيب فكرة من افكار مسائل الكتاب\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nA\n\nالصوت:\n\nعالي وواضح جدًا من غير ازعاج\n\nإضافات\n\nالدكتور والله انسان حبيب وطيوب وراعي نكته ويتفهم وضع الطلاب وانصح فييه جدددددا\nغير هذا متسااعد جدا في الكلاس ورك يعني اذكر كويزين سويت فيهم بيرفكت وكوزين جبت فيهم العيد (يعني فعلا العيد بمعنى الكلمة هههههه) لكن سلمت كل الهوموركات وكان عندي من غياب الى غيابين وعطاني 60/60 في الكلاس ورك\n+ التصحيح اشوفه ممتاز وايضا الى رحت له المكتب ووريته مثلا شي ماكان واضح يتقبل يزيدك ويعطيك حقك\n\nبالتوفييق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437688-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/20", "user": "The_lion013", "ts": 1451685930000, "tid": 68385, "pn": 20}}]}', 1451685930000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-heisenberg-math202', 'stk-heisenberg', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 202 152\nلتحضير :بداية الكلاس\nطريقة الشرح :مشكلته بس يحل امثلة الكتاب على السبورة .يجي محضر حق الدرس.\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:b\nإضافات :الميجر الاول كان تصحيحه على السليوشن الميجر الثاني احسن من الاول.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449264-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/22", "user": "HEISENBERG", "ts": 1463437242000, "tid": 68385, "pn": 22}}]}', 1463437242000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-math202', 'stk-kirsty13', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68385", "n": "Dr. K Furati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة: MATH 202\nالفصل الدراسي: 211\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : كل يوم بداية الكلاس ،والمتأخرين يحضرهم بعد الكلاس\n\nطريقة الشرح : معه ورقة A4 منسوخة من الكتاب وينقل المعلومات فيها على السبورة ويعلق ويتشارك معنا فيها . طبعا هو ما عنده نوتة ولا يرفع شي على البلاك بورد . صوته جدا جدا جدا هادئ ويجيب النوم ويشرح على نبرة وحدة وشرحه مو مرة عادي واقل من عادي ، حاولت اركز معه ماقدرت يجيب النوم بشكل فضيع . في كلاسين قدرت اركز معه بشكل كامل وفهمت درس والثاني مو مرة .\n\nالكويزات : اختبرنا 5. سهله , على البلاك بورد . مذاكرة سريعة بسيطة تقدر تاخذ فل مارك او حولها بالراحة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالصوت: ضعيف ويجيب الملل\n\nالقريد النهائي: اعطي الدكتور +C\n\nإضافات : بالنسبة للهوموركات كان يعطينا اسئلة اقل من المطلوبة بكثير للأمانة ، لكن مشكلته عنيد ولا يأجلها الا بالموت ، كان ينزلها في اوقات المياجر والاوقات الحرجة الله يهديه ، الكويزات كان يحدد لنا وقتها قبل باسبوعين . بالنسبة للتصحيح فأشوفه كويس مرة والرجال يراعي للأمانة ولا يمشي على السلوشن بالحرف . اشوف الدكتور خيار ممتاز للسلف ستدي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533244-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/k-furati/68385/30", "user": "Kirsty13", "ts": 1641114041000, "tid": 68385, "pn": 30}}]}', 1641114041000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmahm50-math202', 'stk-ahmahm50', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68403", "n": "Dr. Mustapha Kassem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 Term 163\n\nالتحضير : في نص الوقت تقريبا يمرر ورقة التحضير على الطلاب.\nطريقة الشرح : ممتازة بالنسبة لي. يشرح من النوته حقته على السبورة و يحل امثلة .\nالكويزات : كانت سهلة صراحة. بنفس مستوى المياجر . لكن مياجر ماث 202 سهله.\nالمياجر: كومن .\nالفاينلات : كومن\nالقريد النهائي : +A .\nالصوت: واضح\nإضافات :\n1- الدكتور كان متعاون معانا حيل من ناحية تحديد أوقات الكويزات و تسليم الهومورك.\n2- زي ما هو مذكور فوق، ما يتحمل احد يمسك الجوال في المحاضره ابداً.\n3- بالنسبة لتصحيحه أختلف مع التقييم اللي فوقي . تصحيحه كان بالملي و الاختبارات كانت كلها written .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479207-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustapha-kassem/68403/39", "user": "ahmahm50", "ts": 1503526658000, "tid": 68403, "pn": 39}}]}', 1503526658000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_alhassan-math202', 'stk-ali_alhassan', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68403", "n": "Dr. Mustapha Kassem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM 192\nMATH 202\n\nيحضر بداية الكلاس و ما يقبل التأخير و لازم يهزأ اذا تأخرت، ما يسمح بأستعمال الجوال اببببدا.\nبالنسبة لي الدكتووور شرييييييح شرحه كان ممتاز و تصحيحه احلى بعد و كويزاته تعتبر اصعب من غيره من الدكاتره ولكن كان فعلا يخليك تستعد للميجر.\nالدكتور محترم و حبيب الي ما عنده مشكله في التأخير فالدكتور بيكون مناسب لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521967-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustapha-kassem/68403/42", "user": "Ali_Alhassan", "ts": 1589172915000, "tid": 68403, "pn": 42}}]}', 1589172915000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-math202', 'stk-rapls', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68403", "n": "Dr. Mustapha Kassem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math202-192\n\nالتحضير : يمرر ورقة كشف أثناء الكلاس , وأحيانًا هو يحضر وأحيانًا يشيك ع التحضير\nطريقة الشرح : يشرح من نوتة هو مسويها ممتازة وتؤدي الغرض لكن لا تغني عن الكتاب\nالكويزات : كويزاته سهلة إلى متوسطة وواحد بس كان صعب\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: +A\nالصوت: واضح تقريبًا\nإضافات : الدكتور ممتاز جدًا ومتعاون مع الطلاب بشكل كبير من ناحية الحضور والتأخير ويمشي كثير ومن ناحية الواجبات , خلوق ومحترم ومتساعد بالمكتب , يشرح لك بأبسط الطرق ويقنعك بأسلوبه , وتصحيحه ممتاز جدًا جدًا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522703-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustapha-kassem/68403/43", "user": "Rapls", "ts": 1591379762000, "tid": 68403, "pn": 43}}]}', 1591379762000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-math202', 'stk-abo_yazeed6', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68404", "n": "Dr. A Bokhari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا ادرس عنده حاليا math 202 ترم 131\n\nطبعا هو اشفاق بخاري مو محمد بخاري عشان ما تلخبطون بينه وبين الثاني\n\nبصراحة كنت أحسب اني نزلت عند مدرس دمار من الردود اللي قريتها هنا\n\nباختصار الرجال شرحه عادي وتقدر تفهمه وممكن تطلب منه يعيده لك ,\n\nطريقة شرحه انه عنده نوت حال فيها أغلب أسئلة الكتاب ويقعد يعرض طريقة الحل للطلاب على السلايدات واذا كان السؤال صعب ,راح يحله على السبورة\n\nوالكورس عموما سهل ممتنع ,عندك مجموعة قوانين تعرف تطبقها بتحل ,ما تعرف بتجيب العيد ,وتركاته قليلة ومتكررة في الأولد اقزامز\n\nتصحيحه لميجر 1 كان بطل والميجر الثاني الأسبوع الجاي والكلاس وورك ما أدري عنه لأنه لسه ما خلصنا,والله يكتب لنا ولكم التوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1292600-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-bokhari/68404/26", "user": "abo_yazeed6", "ts": 1385200254000, "tid": 68404, "pn": 26}}]}', 1385200254000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11724-math202', 'stk-user11724', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68404", "n": "Dr. A Bokhari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term201 - Math202\nالتحضير: نهاية كل محاضرة ينادي بالارقام\nطريقة الشرح: يكتب على تابلت في النوت ويشرح اسئلة الكتاب (اشبه بملخص للكتاب)\nالكويزات : وسط واغلب الكويزات كان افرجها 50% الى 60% وزادنا في الاخير الى 70%\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: واضح ولكن فيه لكنة هندية خفيفة\nإضافات: الدكتور شخصيا ما عجبني شرحه وكانه يقول اشياء حافظها او اشياء محلولة في ورق قدامه وهو ينقلها بس، كان فيه طالب وحيد الي يتابع مع الدكتور ويشارك معه، اغلب الي شفتهم ساحبين عليه، انا اخذت المادة سيلف ستدي وتابعت مقاطع الدكتور مصفى قاسم، الي نظامه سيلف ستدي ممكن يكون الدكتور كويس لان وقت تحضيره ثابت وما يركز في الهوموركات كثير، كان يطلب مننا بروجكتات (تقريبا 6) وتكون سؤال نسلمه قبل الكلاس الجاي، وما ادري هل حسبها بضمير في النهاية ولا وزع الدرجات عشوائي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528025-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-bokhari/68404/47", "user": "user11724", "ts": 1611176747000, "tid": 68404, "pn": 47}}]}', 1611176747000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-math202', 'stk-abdulla_yahia', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. بدر الحميدي ]\n\nMATH 202 - Term 141\n- التحضير : غالباً - ورقة تعدي على الطلاب ، لكن فيه مرات كثيرة ما يحضر …\n\n- طريقة الشرح : يشرح على السبورة - شرح ممتاز و واضح جداً + نوته يغني عن الكتاب تقريباً …\n\n- الكويزات : أعطانا 3 كويزات و كلاس تيست أقل من المتوسطة من النوتة …\n\n- المياجر : كومن …\n\n- الفاينلات : كومن …\n\n- القريد النهائي : A\n\n- الصوت : واضح و سلس لكن النطق الإنجليزي سيء إلى حد ما …\n\n- إضافات : الدكتور محترم و بشوش + تصحيحه كويس …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422440-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/78", "user": "Abdulla_Yahia", "ts": 1422283193000, "tid": 68406, "pn": 78}}]}', 1422283193000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdelaziz-math202', 'stk-abdelaziz', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 - 161\n\nالتحضير :\nبداية السمستر كان التحضير بورقة تمر عالطلاب لمدة اسبوعين الى شهر ما اذكر بس بعدها صار مايحضر\n\nطريقة الشرح :\nعنده نوت خاص فيه ممتاز وشامل تقريباً. يكتب التعاريف بداية كل سكشن وبعدها يبدأ يحل الاسئلة اللي بالنوت\nبعض الاسئلة تحتاج تكتب حلها او تصوره لان مب كلها محلوله\nطريقة شرحة هي الافضل بالنسبة لي لانه يعلمك البروسيجر وتمشي عليه ومايتفلسف فيه واجد\n\nالكويزات :\nعطانا 6 وخذ افضل 5\nالاسئلة من متوسطة الى صعبة بس تراها مهمة\nجانا سؤال في الميجر نصاً من الكويز\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي: +A\n\nالصوت:\nواضح جداً ولغته سهلة\n\nإضافات :\nالدكتور افضل دكتور مر علي في قسم الماث كله شرح واخلاق ماشاء الله تبارك الله\nشرح وتصحيح ممتاز، افرج كلاسه من اعلى الافرجات\nالهومورك مايدقق عليه ولا يهمه قليل اللي طلب مننا نجيب هوموركات\nوفي الاخير الكلاس وورك بيضها ماقصر معانا\nاذا منزل كورس غير 202 بنزل عنده بدون تفكير\nيعجبني الدكتور الي يعطيك اللي يفيدك ولا يلخبطك بكثرة الاكسسوارات\nلان الكورس نفسه فيه طرق حل كثيرة بس لو فهمت معاه من البداية بتعرف كل شي وين تستخدمه\nنقطة ايجابية للدكتور سوى قروب Whatsapp واضاف طلاب السكشنين وصار يجاوب على الاستفاسارات في القروب ويطرح اسئلة والكل مستفيد، اضافة على انه يحط حلول بعض الاسئلة الي يحلها مع حلول الكويزات\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466815-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/84", "user": "Abdelaziz", "ts": 1485123304000, "tid": 68406, "pn": 84}}]}', 1485123304000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-math202', 'stk-mr.a1', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 162 MATH 202\n\nالتحضير :\nنادر جدا ، وإذا حضّر يمرر ورقة التحضير بداية الكلاس وكل واحد يحط صح عند اسمه.\n\nطريقة الشرح :\nشرح كامل على السبورة. يبدأ المحاضرة بذكر الأشياء اللي بيشرحها بشكل سريع. يتكلم عن المفهوم الأساسي ، يشتق القانون -أحيانا- قدام الطلاب ، ويحل مسائل كثيرة على كل نقطة.\nاللي ما يحب يكتب بيرتاح مع الدكتور ، النوتات كلها على البلاك بورد جاهزة ، لكن خذ معك دفتر لأنه أحيانا يضيف سؤال اولد اقزام على النوت أو يسوي تعديل معين عليها. مرات يحل بطريقة مختلفة عن النوت فتحتاج تسجلها معه -خصوصا في تشابتر ٦-.\nشرح رائع جدا ، خلّص المحاضرة وراجعها في نفس اليوم وتقفّل على الدرس -بعدما تتدرب طبعا-.\n\nالكويزات :\nاعطانا ٤ كويزات ، مستواها متوسط. الأسئلة يجيبها من الأولد اقزام وأسئلة الكتاب. أعطى كويز اختياري خامس للي يبي يحسن درجته وقال بس باخذ أفضل أربعة.\n\nالمياجر:\nكومون ريتن. تصحيحه ممتاز جدا.\n\nالفاينلات :\nكومون ريتن ، ما اختبرنا للحين.\n\nالقريد النهائي:\n+A\n\nالصوت:\nصوت واضح ومسموح ، أغلب الشرح بالانجليزية.\n\nإضافات :\n١. د. بدر الحميدي من أفضل الدكاترة اللي درست عندهم خلقا وعلما. غير إنه فاهم ويعرف كيف يوصل المعلومة للطلاب في أبسط صورة فهو قريب منهم ويسولف مع الطلاب ، وقلبه على الطالب أكثر من الطالب نفسه. مواقف شفتها بعيني هالترم أثبتت هالشيء.\n٢. الدكتور يتضايق من الطلاب اللي يتأخرون حتى لو هو ما يحضّر ، ونفس الكلام عن اللي ما يركزون معه في الشرح أو يستخدمون الجوال.\n٣. ممكن السلبية الوحيدة في الدكتور هي واجباته -وهذا طبعا في ماث ٢٠٢-. كل اسبوعين إلى ثلاثة أسابيع تقريبا يعطينا ٣-٤ سكاشن في هومورك واحد ، نحل كل الأسئلة المذكورة في السيلبس لكل سكشن ، فيطلع لك هومورك أبو ٢٥-٣٠ سؤال ، ويحتاج حوالي ١٥ صفحة A4 عشان تخلصه. هو يفيدك كتدريب لكن اللي يؤجل كثير وما يحل الأسئلة أول بأول بيتراكم عليه.\n\nختاما ، إذا يحصل لك تاخذ كل كورسات الماث مع د. بدر الحميدي ، أنصحك ما تفوّت هالفرصة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473466-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/85", "user": "Mr.A1", "ts": 1495264216000, "tid": 68406, "pn": 85}}]}', 1495264216000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4459-math202', 'stk-user4459', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68411", "n": "Dr. Muhammad Bokhari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا الحين يدرسني math 202\n\n--\n\nالتحضير : شديد جدا بس لمصلحة الطالب .\n\nطريقة الشرح : ممتازه جدا ويفهمك المسئله بطريقته الخاصه لان الكتاب مو سهل للفهم.\n\nالكويزات : متوسطة المستوى وغالبها من النوت الي يكتبه .\n\nالقريد النهائي: A+ بلا مجامله 🙂\n\nالصوت : عايدي ولهجته مفهومه .\n\nاضافات : انا انصح به وبقوه للي راح يركز معاه , هو يعطينا الحين هومووركات نجلس عليها يوم او يومين ويالله نحلها بس لمصلحتنا , انا حليت الهوموورك ووتعبت عليه وجيت عند الميجر وشفته ولا شي مقارنة بالهوموورك , صح انت بتتعب معاه لكن راح تستفيد منه في المياجر حتى وان جبت درجات نازله في الكويزات والهومووركات .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p600448-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-bokhari/68411/12", "user": "user4459", "ts": 1273102534000, "tid": 68411, "pn": 12}}]}', 1273102534000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali-che-math202', 'stk-ali-che', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تيرم 142- Math202\nالتحضير\\ بداية الكلاس ومو دايما\nالشرح \\ يشرح باستخدام البورد بس اخر سكاشن من سلايدات ودايم يسولف عن التطبيقات\nالدكتور يطير في المتيريال كل كلاس سكشن جديد ذا عيبه\nالكوزات \\( 4 او 5 )سؤال واحد فقط في الكوز والتصحيح سيء لكن حذف اسوأ كوز لكل طالب\nالمياجر \\ رتن والتصحيح بالملي انسى تحصل بوينت بالغلط\nالكلاس ورك \\ سلم الهوموركات كلها + لا تغيب وراح تحصل تقريبا فل او اقل بشوي بغض النظر عن كوزاتك\nالقريد النهائي C+\n\n>>>> لا تستخدم الجوال اثناء المحاضره لان راح يفشلك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424744-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/31", "user": "Ali-CHE", "ts": 1440077661000, "tid": 68413, "pn": 31}}]}', 1440077661000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9213-math202', 'stk-user9213', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 151 - Math 202\n\nالتحضير : شبة دائم , ورقة تمر عالجميع.\n\nطريقة الشرح : موب كويسة صراحة يكتب أمثلة و قوانين من غير تحضير يعني يفكر فيها ثم يكتب وما يجي محضر ومثل ما قال البعض ما تدري وين بدا ووين انتهى الدرس.\n\nالكويزات : سهلة و قليلة.\n\nالمياجر : كومن.\n\nالفاينلات : كومن.\n\nالقريد النهائي : أعطيه C .\n\nالصوت : واضح .\n\nإضافات : الكورس سهل طلعت بقريد طيب واذا حصلت غيره لا تاخذ معه . كلام الشباب فوق عن الهوموركات صحيح تماما. الاخلاق زينه بس المشكلة بطريقة التدريس والتصحيح الكارثي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437713-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/35", "user": "user9213", "ts": 1451717135000, "tid": 68413, "pn": 35}}]}', 1451717135000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_aviator-math202', 'stk-the_aviator', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم…\nTerm 151 ----- math 202\nالتحضير: ورقة تمر عليك ولا ينادي الاسماء ويشيك ، احيانا يحضر واحيانا ينسى.\nطريقة الشرح: سيء جدددددددددا ولا يعتمد عليه. يجي المحاضرة غير مستعد. الأمثلة الي يحلها على السبورة يألفها تأليف وهو يشرح. يعني يجي يرمي عليك theories مع حلول مفقوعة ولا همه انت فهمت ولا لا. وكل هذا بسبب طريقته الفوضوية في توصيل المعلومة.\nالكوزات: يكتب ال quiz على السبورة ويخليك تطلع ورقة وتحل. وغالبا السؤال متوسط الى سهل \" إذا ذاكرت \"\nالمياجر والفاينلات: common\nالصوت: واضح\nاضافات: فيه عيب يرفع الضغط. التصحييييح. ما يعترف بشي اسمه procedure او steps او partial credit. اذا كان على السؤال 14 درجة وحليته على الخطوات وغلطت في آخر خطوتين بس يعطيك 4 من 14 .\nباختصار المادة سهلة وتقدر تجيب فيها قريد بس يبغالها دكتور تصحيحه كويس. هذا انحش منه لانه دمار في الدرجات.\nالقريد النهائي: d+ وكثيرة عليه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437879-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/36", "user": "THE_AVIATOR", "ts": 1451822531000, "tid": 68413, "pn": 36}}]}', 1451822531000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_ali-math202', 'stk-abo_ali', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68467", "n": "Dr. Mahmoud Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math202\n\nالتحضير :\nينادي بالاسامي , لكن مش كل مره يحضر , وغالبن يحفظ الوجيه و يحسسك انك وشسمه اذا غبت\n\nطريقة الشرح :\nيكتب في السبوره , يقدس الكتاب والامثله, يرجعلها كثير , نادرا ما يطلع من الامثله اللي بالكتاب\n\nالكويزات :\nماكان عنده كوزات , بس كلاس تستات في المساء , اذكر انها كانت 3 وكل وحده عليها 40 من 400 ,\n\nالمياجر:\nكومن\n\nالفاينلات :\nكوموووون\n\nالقريد النهائي:\nمدري وش اعطيه , الكورس نفسه غبي , والدكتور الله يعطيه الصحه والعافيه ويحسن ختامه كان مشدد شويات عليه , فما ارتحت له 😦\n\nالصوت:\nجيد , ومرات يبح صوته ويتغير , الله يرزقه الصحه والعافيه\n\nإضافات :\nاول مره يمر علي انسان مثل كذا , يحب يدرس مع ان له اكثر من 40 سنه في مجال التدريس , والادهى من كذا ان له نفس يدرس ويطلع الجبل ويسوق بعد ,\nانسان مكافح وصبور , ويعاملك مثل حد عياله\n\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1381731-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mahmoud-sarhan/68467/71", "user": "Abo_Ali", "ts": 1403434589000, "tid": 68467, "pn": 71}}]}', 1403434589000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-math202', 'stk-guest', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m70511", "n": "Dr. Ahmad Bonfoh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 192 (زمن الكورونا)\n\nالدكتور: Ahmad Bonfoh\n\nالمادة : Math 202\n\nالتحضير : اخر الكلاس يقرا الاسماء\n\nطريقة الشرح : من جنبها شوي موبذاك الزود.\n\nالكويزات : سهله متوسطة + شيك الاولد كويزز حقته يجيب نفس الافكار غالباً.\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالتصحيح: ممتاز ويدف.\n\nالقريد النهائي: A+\n\nالصوت: جيد\n\nإضافات :يقبل ميكب طول الترم او كلاسات معينه، ونيس ويضحك وكلاسه جداً ممتع وردود فعله تضحك، الدكتور طيب جداً وممتاز بغض النظر عن الشرح لان الماث اشوف انه سلف ستدي خاصه ٢٠٢ يعني.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521957-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-bonfoh/70511/36", "user": "Guest", "ts": 1589153760000, "tid": 70511, "pn": 36}}, {"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 - ترم الكورونا\nما قبل الجائحة فقط\n\nالتحضير\n: يومياً نهاية الكلاس ، عن طريق السيريال نمبر .\n\nطريقة الشرح\n: يشرح النوتات حقته ويكتب على السبورة لكن الوضع ملخبط مره يكتب مره يشرح وخطه مره سيء.\n\nالكويزات\n: أختبرنا كويز واحد قبل الحظر , كان سؤالين يشبهون أسئلة الواجب وتصحيحه فيهم غير واضح وملخبط.\n\nالواجبات\n: كل يوم أحد نسلم واجب عن درسين تقريباً.\n\nالصوت\n: غير واضح و صعب تفهمه, يتكلم مره بسرعه.\n\nالميجر\n: أختبرنا الأول رتن وتصحيحه فيه كان مره شديد ويمشي على المانيوال بالضبط.\n\nإضافات\n:\n\n- يصحح الميجر والكويز بسرعة حرفيا الكلاس اللي بعده يكون مصحح.\n- اذا كنت من النوع اللي تعتمد على الدكتور في الشرح فما أنصحك فيه لأنه عنده صعوبه في إيصال المعلومات والشرح سيء وحتى الصوت.\n- ما يحب يشوف أحد يطلع الجوال , مره متشدد من ذي الناحية. اذا شافك ممكن يهزئك قدام الطلاب.\n- سوا لنا هيلب سشن وحده قبل الميجر الأول.\n- بالنسبة للتأخير ما يحبه وأحياناً يهزئ وأحيانا يتغاضى.\n- نظامة في الغياب مافيه خصم بس لين توصل للـDN.\n- كان مسوي لنا قروب واتس ويخلي الأدمن يصور السبورة ويرسل ويجاوب على الأسئلة.\n- نظامه في تصحيح الكويز غير واضح وحتى تقسيمه الأسئلة والخطوات.\n\nبالمختصر\n:\nالدكتور شرحه غير مجدي وشديد من ناحية التحضير والتصحيح , لو كنت تعتمد على الدكتور في الكورس بتضيع حرفياً , خاصتاً انه الكورس مهم لطلاب الهندسة , ولو عاد بي الزمان حدور غيره وما راح أنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522236-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/49", "user": "Guest", "ts": 1590061898000, "tid": 68471, "pn": 49}}, {"id": "stk-dr-m118565", "n": "Dr. Abdulilah Kadri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه MATH202 الفصل 201 أون لاين\n\nالتحضير :\nكان يقول لنا أنه ياخذ التحضير لكن احس انه ما ياخذ بس الدكتور كان ينادي على الطلاب اللي ما يشاركون ويستفسر إذا كانوا متابعين مع الشرح ولا لا.\n\nطريقة الشرح :\nشرحه ممتاز و واضح وضوح الشمس يكون مجهز نوتات قبل الكلاس مكتوب فيها كل المفاهيم وراح يرسلها لك إذا بغيت ترجع لها وبعد ما يخلص شرح المفاهيم وتوضيحها يكون في امثلة بالنوتات يحل الأمثلة اللي يقدر عليها وطريقة الحل يفتح كام ويحل الاسئلة يدوي قدامك والاسئلة الباقية يشجع الطالب يحلها بوقت فراغة.\n\nالكويزات :\nسهلة إلى متوسطة بالإضافة الدكتور كان متساعد مرة من ناحية الكويزات كان يوفر وقتين لبعض الكويزات اذا ما قدرت تحضر الاول تقدر تحضر الثاني طبعًا الاسئلة غير بالإصافة إلى أنه تساعد معنا بحيث إذا خبصت بالأول تقدر تحضر الثاني لكن راح ياخذ الافرج بينهم. مع كل ذي المساعدة ساعدنا ايضًا بأنه زود كويزين وخذ درجة افضل خمس كويزات.\n\nالمياجر:\nالمياجر سموها Online assessment وكان على الواحد منها 15% بالإضافة أنهم اضافوا ميد عليه 15% وكان كل الاسئلة اختياري لكل الاختبارات. كلها كانت سهلة ما عدا الميد كان الكوردنيتر يستهبل بدال ما يختبر فهم الطالب للكونسبت كان يجيب اسئلة طويلة بحسابات طويلة عشان الطالب يتلخبط بالسؤال أو يضيع فيها وقت أطول من اللازم بحيث أنه ما يكون معه وقت كافي لحل الاسئلة الباقية وهذا ازعج كثير من الطلاب لان الاختبار كان سهل لكن خربوه بذي الطريقة.\n\nالفاينلات :\nنفس الطريقة وكان سهل الاختبار.\n\nالقريد النهائي:\nالحمدلله طلعت ب A+\nبالنسبة للدكتور A+ الرجل شريح ومتساعد لأبعد درجة.\n\nالصوت:\nواضح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527695-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulilah-kadri/118565/28", "user": "Guest", "ts": 1610081613000, "tid": 118565, "pn": 28}}]}', 1589153760000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8521-math202', 'stk-user8521', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math202_122\nدائما يشرح الكونسبت بسرعة وما يركز عليه, لكنه يحل مسائل كثير\nما أعطانا الا ثلاث كويزات, قبل كل ميجر وقبل الفاينل, وكانت طويلة وتحتاج وقت واغلبها من الاولد اقزام\nما أعطانا الكلاس وورك الا قبل الفاينل بيوم , والآفرج كان نازل لدرجة انه رفع كل واحد 10 درجات\nعموما الدكتور يكفي لو ما يجي منه الا أخلاقه وتعامله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1232347-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/27", "user": "user8521", "ts": 1370482463000, "tid": 68568, "pn": 27}}]}', 1370482463000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-voldy-math202', 'stk-voldy', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math202 - Term 122\n\nالتحضير : في وسط الكلاس ينادي بالأسماء\nطريقة الشرح :ممتازة لكن ما يركز مرة على الكونسبت\nالكويزات : ثلاثة سهلة من الأولد إقزام\nالمياجر:كومن ويعطيك أكثر من حقك\nالفاينلات : كومن\nالقريد النهائي:A+\nالصوت:جدا واضح\nإضافات : قمة في الأخلاق وأنا دايما أنتظر كلاسه ودايما ينكت في الكلاس\nلو تيسر انك تنزل معاه لا تتردد أبدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1318751-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/28", "user": "Voldy", "ts": 1389615907000, "tid": 68568, "pn": 28}}]}', 1389615907000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-math202', 'stk-ad0rs', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68568", "n": "Dr. Husain Al-Attas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 T131\nالتحضير :\nنهاية كل كلاس\nطريقة الشرح :\nشرحه ممتاز\nيشرح الثيورم أول بعدين يحل اقزامبل من الكتاب وأحيانا أولد اقزامز\nبس سررييييع في الكتابة ما شاء الله\nالكويزات :\n3 كويزات من الاولد اقزامز طويييلة أظن 5 أسئلة\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nA+\nالصوت:\nواضح\nإضافات :\nالدكتور أخلاق وشرحه ممتاز\nتصحيحه شبه شديد\nكان شبه شديد في تصحيح ميجر 1\nبس في الفاينل اتساهل معي كثير الله يجزاه خير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1321968-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-attas/68568/29", "user": "ad0rs", "ts": 1390602188000, "tid": 68568, "pn": 29}}]}', 1390602188000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-math202', 'stk-hammmod', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68575", "n": "Dr. Mohamed El-Gebeily", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : Term 152 MATH 202\n\nالتحضير : يوميا بداية الكلاس ينادي بالأسامي. ويطرد المتأخر فوق 10 او ربع ساعة\n\nطريقة الشرح : يكتب الديفينشنز بشكل واضح ومختصر بداية الكلاس وبطريقة مغايرة للي في الكتاب شوي ويبعدين يبدأ في الاكزامبلز. ساعات يكتب الديفنشن من راسه ما ينقله من النوت ويدلك انه فاهم وش قاعد يسوي. شرحه جيد بالعموم ومناسب، مدري هو رائع والا الكورس سهل وما فيه مفاهيم صعبة!\nالكويزات :\nخمس كويزات، معظمها متوسطة الى سهلة نفس أسئلة الكتاب، الا واحد حق درس 4.1.2 و 4.1.3 جابلنا كويز صعب، وحجته ان اسئلة الكتاب Trivial وما تواجه -___-\n\nالمياجر: كومون وتصحيحه رائع جدا بالنسبة لي.\nالفاينلات :\nالقريد النهائي: A\nالصوت: واضح ويتكلم مخلط عربي على انجليزي.\n\nإضافات : الدكتور يستظرف كثير، مرات يضحكني وأغلب الوقت أشوفه سامج :D، أشوفه مناسب لهالكورس.\nعادي تذاكر مادة ثانية أو تطقطق عالجوال أو تنام ما يقول شيء.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446753-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-el-gebeily/68575/32", "user": "hAmMmOd", "ts": 1460753206000, "tid": 68575, "pn": 32}}]}', 1460753206000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dyaa94-math202', 'stk-dyaa94', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68575", "n": "Dr. Mohamed El-Gebeily", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "161 - MATH 202\n\nمتمكن من الماده وشريح…ع السبورة والنوتس يحطهم ع البلاكبورد قبل مايجي الكلاس…يعني زين للي مايحب يكتب…الدكتور فلاوي ويحب يقط قطات وكلاسه مو ممل + متعاون في اوقات الكوزات والهوموركات…\n\nنجي للكوزات…متوسطة…تصحيحه جيد…وفي المياجر والفاينل تصحيحه عسسسل ويساعد كثير.\n\nهوموركات…طلب 8…واخذ افضل 6…من الكتاب طبعا.\n\nنجي للسلبية الوحيده اللي شفتها فيه…الكلاس ورك…هو من 60 ومعظم الدكاترة وكل الدكاترة اللي درسوني ماث قبله كانو يحطون 20 للواجبات و 40 للكوزات بس هو حط 15 للواجبات و 45 للكوزات وهذا اللي نزل درجات الشباب في الكلاس ورك مع انه الافرج حق الكوزات كان نازل…ويوم حط الكلاس ورك النهائي حطه بزياده لاتذكر عكس كل المدرسين اللي درسوني من قبل…بس هاذي السلبية الوحيده اللي شفتها فيه ويمكن البعض مايعتبرها سلبية…الرجل يعطيك حقك وهو له حرية التعديل ع ال60.\n\nOtherwise…he’s greatttt\n\nاعطيه 8/10 والله يعطيه العافيه…وبالتوفيق للكل…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466584-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-el-gebeily/68575/33", "user": "Dyaa94", "ts": 1484815208000, "tid": 68575, "pn": 33}}]}', 1484815208000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-way_to_aim-math202', 'stk-way_to_aim', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math -202\nsem 122\n\nالشرح: لابأس به , يحل أسئلة كثيرة الكتاب .\nالكوزات : من أسئلة الكتاب ( Exercises) يأخد أحسن 5 من 7 كوزات\n\nالسلبيــــــــــــــــــــــــــــــــــــــــــــــــــات\nتصحيح المياجر يمشي فيه على تصحيح الكوردنيتر و كانه كتاب منزل.\nالكلاس ورك ما يحاول رفع أفرج الكاس ورك أبدا زي باقي االدكاترة إلى درجة أن ما في أحد خذ في سكاشنه فل مارك في الكلاس ورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1038666-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/30", "user": "way_to_aim", "ts": 1337205045000, "tid": 68581, "pn": 30}}]}', 1337205045000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-math202', 'stk-user11264', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 - 191\nالدكتور رجائي العصار\n\nالتحضير : بداية الكلاس غالبًا، أي واحد يخش بعد التحضير يعتبر متأخر وهذي النقطة كانت مزعجة جدًا جدًا بالنسبة لي، إذا خشيت متأخر تروح تكلمه آخر الكلاس يحضرك وإذا نسيت بيعتبرك غايب ولا فيه أي تساهل من هالناحية عنده أبدًا.\n\nطريقة الشرح : من النوع اللي يحل كثير بحكم طبيعة الكورس، ما كان يهتم للاثباتات لأنها مب داخلة معنا. ما عنده نوتات ولا شيء وكل حله على السبورة. طبعًا تكرار الحل والمسائل يفيد في أنه يدخل الطريقة بدماغك غصب بما أن الكورس يعتمد على طرق الحل. أشوف شرحه ممتاز لو كنت مركّز معه وفاهم الفكرة بالبداية أما لو فهيت بتقعد باقي المحاضرة ضايع. نقطة مهمة أخرى، الأشياء اللي مرّت عليك في كورسات الماث السابقة الدكتور ما يتعمّق فيها لأن حسب وصفه هذا كورس differential equations مب كورس مراجعة، تضررت من هالنقطة شوي لكن مب مرّة.\n\nالكويزات : متوسطة، مرات تكون سهلة ومرات تكون صعبة ومرات سهلة بس الوقت ضيّق وما يساعد. طبعًا بالصعوبة أقصد أن حلها طويل ولا الكورس أصلًا عبارة عن procedure. تصحيحه في الكويزات جلد باختصار\n\nالمياجر: كومن بس كل دكتور يصحّح لطلابه، تصحيحه بالمياجر أشوف أنه أهون من الكويزات، ممكن لأن عنده تصحيح الكوردنيتر ويمشي عليه. التصحيح عمومًا جيد جدًا، لو وصلت إلى آخر الحل وعندك غلط حسابي فوق بيخصم عليك درجتين تقريبًا أو حسب اللي محدّده الكوردنيتر، إذا شافك فاهم الفكرة ما بيخصم كثير وهكذا، باختصار يمشي على تصحيح الكوردنيتر وأحيانًا يتساهل فيه شوي.\n\nالفاينلات : نفس المياجر\n\nالصوت: يفضّل تقعد قدام أو بالوسط لأنه واطي شوي\n\nالقريد النهائي: ِA\n\n* الدكتور أخلاقه عسل، وطيّب جدًا وممتاز وشرحه رهيب، من أفضل اللي درسوني ماث حقيقةً\n* تصحيحه مجملًا جيد جدًا\n* التحضير أكبر سلبيّة له، لو كان أول كلاس لك وما تضمن أنك تجي قبل بداية الكلاس فحاول تعيد النظر فيه\n* آفرجه في الكويزات غالبًا نازل لذلك آخر الترم زود الكل 10 بوينت من 60 (حق الكلاس وورك)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519029-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/73", "user": "user11264", "ts": 1578856386000, "tid": 68582, "pn": 73}}]}', 1578856386000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muntathir111-math202', 'stk-muntathir111', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 term 192\nطبعا بقيم اعتمادا على ماقبل الاونلاين\nالتحضير : متشدد بشكل مب طبيعي لدرجة احيانا يحضر قبل بداية الكلاس !! ولو تتأخر ثانية انت غايب وعليها خصم !\nايضا ذكر باول كلاس اذا ماتقدر تجي مبكر غير السكشن. بس فعليا صعب تغير السكشن بعد مابدا السمستر!!\n\nطريقة الشرح : بالسبورة\nالكويزات : سهلة ومن الكتاب\nالمياجر: تعتمد على الكوردنيتر (ايضا تصحيح الدكتور ممتاز)\nالفاينلات :\nالقريد النهائي: اعطيه C والسبب بالاضافات\nالصوت: واضح\nإضافات :\nممكن تستغربون من التقييم بس صراحة الدكتور ماصلح لي\nشرحه ممل ومارفع اي ملف بالبلاكبود يعني لازم تكتب وراه عشان النوتات وهذا ابدا ماحبه لاني وانا اكتب تضيع علي نقاط بالشرح .\nايضا اذا تبي تصورالسبورة لازم تجلس قدام بالصفوف الامامية عشان يتأكد انك ماتستخدم الجوال (طبعا مايمدي تلحق على الكراسي الامامية الا لو جيت مبكر حيل )\nومن ناحية الشرح استغرب من المدح فوق. انا دارس عند الدكتور محسن الشهراني والدكتور بدر الحميدي ومايتقارن بمستواهم بتوصيل المعلومة وبالمتعة اثناء الكلاس.\nونظامه بالتحضير سيء لدرجة انه يغطي على الايجابيات المتبقية عنده.\nايضا سألته هل بتمشي غياب او غيابين بحكم ان احيانا تصير ظروف قاهرة ومايقدر الطالب يجيب عذر. رد علي رده الشهير\" نشوف نهاية الترم \".", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521989-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/76", "user": "Muntathir111", "ts": 1589262613000, "tid": 68582, "pn": 76}}]}', 1589262613000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-math202', 'stk-abo-da7m', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68677", "n": "Dr. M Al-Shahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه math202 فصل 142\n\nالتحضير :\n\nيقرأ الأسماء بجواله نهاية كل كلاس، يمشيك إذا تأخرت بس ينبهك.\n\nطريقة الشرح :\n\nيكتب على يسار السبورة المفاهيم الأساسية ، يبدأ يتكلم عنهن ويشرحهن بعدين يبدا يحل أمثلة بوسط السبورة ،، بعض الدروس يستخدم سلايدات.\n\nالكويزات :\n\nطوال شوي ومايلات للصعوبة بس ميزتهن شاملات. يعطي 6 كويزات ويحذف أسوأ واحد ويقيمك على الباقيات.\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\na+\n\nالصوت:\n\nواضح ولغته ممتازة\n\nإضافات :\n\n* الدكتور فاااااااهم لأبعد حد، دقيق جدا وهو يتكلم وتقريبا ما يقول شيء خطأ !🙂\n\n* يعيد ويكرر ويرحب بالأسئلة\n\n* يركز على الصورة الكلية ويجلس يشرح بشكل مجرد ما يعتمد على الأمثلة بشكل أساسي - شخصيا أحب هالنوع من الدكاترة-\n\n* يعيبه أنه مزاجي نوعا ما وبعض الأحيان ينفعل بس يمسك نفسه\n\n* مرتب مرة، مهتم بموقعه الشخصي ويحط الدرجات عليه.\n\n* من ترتيبه يعطيك الكويز واسمك مطبوع عليه بالكمبيوتر، وهذا يعني انه يجلس يوزع الأوراق سنة قبل يبدأ الكويز 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433423-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-al-shahrani/68677/47", "user": "abo-da7m", "ts": 1447639207000, "tid": 68677, "pn": 47}}]}', 1447639207000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9169-math202', 'stk-user9169', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68677", "n": "Dr. M Al-Shahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه math202 ترم 142\n\nوحاليا معه في math280\nالتحضير : يحضر غالبا في أخر المحاضرة\nطريقة الشرح : الشرح ممتاز.\nالكويزات : ما فيه كويزات\nالمياجر:\nالفاينلات :\nالقريد النهائي: ِِa\nالصوت: واضح\nإضافات : الدكتور حبيب ومتعاون", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1434407-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-al-shahrani/68677/51", "user": "user9169", "ts": 1448386014000, "tid": 68677, "pn": 51}}]}', 1448386014000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unknown-math202', 'stk-unknown', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 term 203 ( Online )\n\nالتحضير : مرن بالتحضير بشكل كبير\nطريقة الشرح : أقل من المتوسط ، (إذا تبي شرح فيه أفضل من الدكتور)\nالكويزات : اختبرنا 6 كويزات وكانت متوسطة تقريبا\nالميد : كومن\nالفاينلات : كومن\nالقريد النهائي: أعطيه B+ ، ما ناسبني شرحه\nإضافات : يتميز الدكتور بالتصحيح دكتور كان يحاول يدور اي شي صح حتى يعطيك عليه درجة عكس غيره الي يحاول يخصم قدر الإمكان.\nو أكثر ما يعيب الدكتور من وجهة نظري الشرح\n\nالخلاصة: إذا المادة رتن وفيها مصادر نزل عند الدكتور غيرها دور غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531336-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/77", "user": "unknown", "ts": 1629343471000, "tid": 68928, "pn": 77}}]}', 1629343471000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.n.a-math202', 'stk-m.n.a', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m70511", "n": "Dr. Ahmad Bonfoh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 - 162\nالتحضير : نهاية الكلاس بالاسم وما يدقق على التاخير ويسمح بالميك اب\nطريقة الشرح : ما اتفق مع اغلب الشباب انه شرحه سيء انا اشوفه عادي لو تركز معه شوي تفهم والكورس سهل للامانة. عنده نوته يكتبها على السبورة و يرفعها على البلاك بورد وهذه ميزة فيه النوتة جدا ممتازة وتغنيك تماما عن الكتاب اللي اشوفه صعب الفهم .\n\nالكويزات : صعبة نسبيا بس في الاخير افرج فما تفرق اعطانا 6 كويزات اخذ احسن 4\n\nالمياجرو الفاينلات: تصحيحه بطللللللللل وما ينقص على الاخطاء الغبية كثير حتى لو كانت في البداية او النص\n\nالصوت: واضح , اكسنت افريقي يضحك لكن تتعود عليه بسرعه\n\nإضافات : الدكتورعسل و كلاسه خفيف و يحب ينكت مع الطلاب ويريحك في الواجبات\nالواجبات في هذا الكورس من اغث الاشياء الاصل انه حوالي 20 سؤال كل اسبوع هو يقللها ل 4 اسئلة على كل سكشن يعني 8 اسئلة كل اسبوع و متساهل في الديد لاين\nانصح فيه بقوة لهذا الكورس بالذات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474953-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-bonfoh/70511/31", "user": "M.N.A", "ts": 1497214042000, "tid": 70511, "pn": 31}}]}', 1497214042000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-euler-math202', 'stk-euler', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m70785", "n": "Dr. S Boubaker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 - Sem 111\n\nبنود التقييم :\n\nالتحضير :\n\nشديد ف التحضير , ماعنده ليت , تتأخر اكثر من 10 دقايق بالكثير مايدخلك الكلاص !\n\nطريقة الشرح : ينقل اللي كاتبه ف ورقة عالسبورة ولايشرح لحد مايخلص وبعدها يشرح , يعني يروح نص الوقت وهو يكتب , صراحة ماعجبتني هالطريقة , 🙂\n\nالكويزات : اعطانا 3 كويزات و2 كلاص تيست , يعني حاول ماتضيعها , مختلفة ف الصعوبة , يجيبها من اسئلة الهوموورك او من الاولد اقزامس , 🙂\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: اعطيه D+\nالصوت: واضح جدن , 🌹\nإضافات:\n1) الرجال لابأس ف الشرح بس مو أفضل من غيره , أخلاقه مش ولابد ,\n\n2) شديد ف التصحيح ,اذكر مرة اعطانا كويز واخذت درجة سيئة لأني حليتها بطريقة غير السليوشن ! رحت وكلمته وعدلها لي واعطاني 10 , لذا حاول تتناقش معاه لو شفت انه ظلمك حقك , 🌹\n\n3) طلعت درجات الكلاص وورك وكانت طيبة , ف اعتقد انه جيد ف هالناحية ,\n\nبالتوفيق , 🌺", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970677-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-boubaker/70785/30", "user": "Euler", "ts": 1326922446000, "tid": 70785, "pn": 30}}]}', 1326922446000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abofordan2004-math202', 'stk-abofordan2004', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m70785", "n": "Dr. S Boubaker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 , TERM 201 , ONLINE\n\nباختصار شديد الدكتور مافيه اي ميزة تذكر , وأهم عيوبة كويزاته\n\nكويزاته كان مستواها جدا صعب وبدون مبالغة وتتقارن باسألة المياجر ان ما كانت اصعب ! , واثرت علينا علشان عليها نسبة عالية من القريد 50% ان ما خاب ظني\n\nشخصيا نزلت عنده واضطريت احذف المادة بعد شهر تقريبا لان الكويزات اثرت علي و لو كملت راح ارسب\n\nهذي تجربتي معاه في الاون لاين الله اعلم اذا في الترم العادي بيكون مختلف او لا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526593-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-boubaker/70785/57", "user": "AboFordan2004", "ts": 1604902537000, "tid": 70785, "pn": 57}}]}', 1604902537000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-math202', 'stk-someone33', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m70785", "n": "Dr. S Boubaker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\nMath202 - Term212\n\nبنود التقييم :\n\nالتحضير :يحضر عن طريق السيرل نمبر يعطيك اياه اول يوم بالكلاس ولازم تحفظه ، ويحضر كل يوم مااذكر فيه يوم نسى ولا ماحضر فيه\nطريقة الشرح :يشرح من السلايدات حقته الكونسبت ، والمثال المهم يحله على السبوره بذمه وضمير\nالكويزات : متوسطه الى سهله\nالصوت:واضح جدا ومفهوم رغم الكمامة\nإضافات : الدكتور كنت شايف تققيمات عنه في المنتدى قبل مااسجل الماده وكنت متخوف لكن والله العظيم من اول يوم عنده وانا شفت شي ماشفته بكل الدكاتره اللي درست معهم ماث بالجامعة ، الدكتور اسطوري شرحه واخلاق ومتساعد جدا ولو شفته في اي كورس قادم للماث راح انزل عنده بدون اي تردد ، المشكله والعيب الوحيد انه كل ويكند واجب لازم ويكون بسيط درس او درسين وتصحيحه بالمياجر والفاينل ممتازه جدا ويعطيك اكثر من اللي تستحقه بكثييير\nالتقييم النهائي :10/10", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535036-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-boubaker/70785/60", "user": "SomeOne33", "ts": 1660607552000, "tid": 70785, "pn": 60}}]}', 1660607552000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_sufayan-math202', 'stk-m_sufayan', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m78126", "n": "Dr. E Echi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 182\nالتحضير : كل نهاية محاضرة ماعنده مشكله بالتأخير بس لا تفلونها ويزعل عليكم\nطريقة الشرح : بالنسبة لي شرحه ممتاز واذا كنت تكتب نوته ف هالدكتور بينفع لك لأنه يكتب بالسبورة بشكل منظم ومناسب لأنك تنقله علطول\nالكويزات : متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\nالدكتور تونسي فاهم بشكل كبير ودايم يشرح غير عن الكتاب لكن شرح جميل جدا صحيح بنص الكلاس تحس انك ماتفهم لكن مجرد خروجك من الكلاس وتبدا تحل اسئلة تعرف علطول وتتذكر شرحه , وتصحيح الدكتور يعطيك اكثر من حقك لكن مشكلته شوي بطيء والكلاسوورك ما ادري كيف كان توزيعه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509030-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/e-echi/78126/27", "user": "m_sufayan", "ts": 1556286446000, "tid": 78126, "pn": 27}}]}', 1556286446000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8577-math202', 'stk-user8577', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math202\nبنود التقييم :\n\nالتحضير : آخر الكلاس … وما يدقق على التحضير أو التأخر بس لا تزودها.\n\nطريقة الشرح :\n\nبالنسبة ل202 ما كان عنده نوت مكتوب بيده أو على السبورة كله كان شغل كومبيوتر … في البداية كان يفتح هالنوت ويحل منه على السبورة بعدين صار يفتح الكتاب على البروجكتور ويشرح عليه مع استخدام السبورة … الشرح في بعض الدروس ممتاز بعضها لك عليه.\n\nالكويزات : سهلة إلى متوسطة … دارس بتحله.\n\nالمياجر: كومن\nالفاينلات : كومن\n\nالصوت: واضح … وانجليزيته تحسنت كثير … عموما هو يشرح باللغتين.\n\nإضافات :\n\nالدكتور جدا محترم … تصحيحه بطل غالبا تاخذ اكثر من حقك … كويزاته قليلة وهذي ممكن تكون ميزة أو عيب … لا تهايط انك فاهم كثير قدامه احسه ما يحب الطلاب اللي زي كذا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1382648-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/16", "user": "user8577", "ts": 1403741387000, "tid": 92906, "pn": 16}}]}', 1403741387000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_3lol-math202', 'stk-mr_3lol', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m94261", "n": "Dr. Muhammad Islam Mustafa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202\n\nالتحضير :أحيانا\nطريقة الشرح :يشرح من السلايدات ( بطله) ويحل الامثله على السبوره\nالكويزات : 6 كوزات نفس اسئله المياجر ( ياخذ افضل 4)\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:a\nالصوت:وااضح جدا\nإضافات :\nدكتور حبوب ., متعاون في التصحيح .\nأنصصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p950143-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-islam-mustafa/94261/33", "user": "MR_3LOL", "ts": 1324318473000, "tid": 94261, "pn": 33}}]}', 1324318473000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a-t-m-math202', 'stk-a-t-m', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m94261", "n": "Dr. Muhammad Islam Mustafa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 فصل 111\n\nالتحضير : أغلب الوقت وعادة نهاية الحصة ما عدا مرة حضر أول الحصة عشان حس الطلاب يتأخرون كثير\nطريقة الشرح :سلايدات جدا ممتازة، فيها القاعدة مشروحة وفيها أسئلة يحلها بالصف.\nالكويزات : 6 كويزات وياخذ أفضل 4\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A+\nالصوت:وااضح جدا\nإضافات :\nمن أفضل دكاترة الماث، شرحه مباشر ويوصل لك المعلومة وحله للأمثلة واضح وأحيانا يحل بكذا طريقة عشان يوضح لك الفرق. متعاون جدا مع الطلاب. كل كويز فيه تقريبا درجتين إلى 3 درجات Bonus وتتجمع لك مجموع الكويزات يعني مو بس لكويز واحد. قبل كل كويز يرسل لنا أرقام أسئلة معينة من Old Exams يحطها على الWebCT ويقول حلوها وتجي أسئلة مشابهة مع اختلاف الأرقام. متساهل جدا في التصحيح وسكاشنه أعلى الدرجات في أفرج المياجر. ينصح فيه بشدة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p955963-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-islam-mustafa/94261/34", "user": "A-T-M", "ts": 1325263451000, "tid": 94261, "pn": 34}}]}', 1325263451000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5430-math202', 'stk-user5430', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m94261", "n": "Dr. Muhammad Islam Mustafa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 202 - 111\n\nالتحضير :\n\nيوميآ بالارقآم …\n\nطريقة الشرح :\n\nيشرح من سلايدات … وشرحه كويس\n\nالكويزات :\n\nيحدد لنا اسئلة ميآجر … ويجيب لنا منها\n\nالمياجر:\n\nكومن + تصحيحه حلو كثير\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\nA\n\nالصوت:\n\nواضح\n\nإضافات :\n\nالدكتور محمد حبيب جدا و يدف بالكلاس وورك و تحضيره يومي\nلكن مشكلته ما يرضى بالميك اب … 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1049354-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-islam-mustafa/94261/38", "user": "user5430", "ts": 1338630980000, "tid": 94261, "pn": 38}}]}', 1338630980000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bo5bo5-math202', 'stk-bo5bo5', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m94261", "n": "Dr. Muhammad Islam Mustafa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 - Term 122\n\nالتحضير :\n\nغالبا نهاية الكلاس بالأرقام وبعض الأحيان في نص الكلاس بس في فترة شاف الناس\nيتأخروا كثير فكان يحضر بعد 10 دقايق من بداية الكلاس بعدين رجع يحضر نهاية الكلاس وما عنده مشكلة تتأخر إلى دقيقة بس إذا خلص التحضير قبل ما تجي تعتبر غائب\n\nطريقة الشرح :\n\nمن السلايدات كونسبت وأسئلة غير محلولة هو يحلها عالسبورة فالأفضل تكتب معاه, شرحه كويس\n\nالكويزات :\n\nمتوسطة الصعوبة , يحدد لكم أسئلة من الأولد إكزام تذاكروا منها ويجي الكويز مثلها أو شبيه بها وهذا الشيء يريحك في المذاكرة للمياجر , ياخذ أحسن 4 من أصل 6 كوزات\nوالحلو أنه بعض الكوزات فيها بونص درجتين أو 4 من 10 , يعني الكويز ممكن يكون من 12 بس هو يحسبها من 10\n\nالقريد النهائي:\n\nB+\n\nالصوت:\n\nواضح\n\nإضافات :\n\nالدكتور هذا حبوب وطيب لكن مشكلته تصحيحه للمياجر بالملي حسب السلوشن بس ممكن بعض الأحيان يتساهل إذا جبت فكرة السؤال أهم شيء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1229460-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-islam-mustafa/94261/39", "user": "Bo5Bo5", "ts": 1369771606000, "tid": 94261, "pn": 39}}]}', 1369771606000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-math202', 'stk-chemist', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m94443", "n": "Dr. Nadeem Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202 Term 102\n\nالتحضير:\nمافيه تحضير ابدا وكلاسي كان الساعة 7ص وكانوا يحضرون 5 من اصل 30 صح ان فيه تحضير شكلي بالورقة ولكن مايعترف فيه وعطانا كلنا في الغياب 10 من 10\n\nالشرح:\nسيئ إلى ابعد الحدود من أسوأ المدرسين اللي مروا علي في الجامعة شرحا باختصار كأنه يشرح لنفسه وذا قرى كأنه يقرا جريدة لا اللي يقرأ جريدة أحسن منه\n\nالكويزات:\nعطانا كويز واحد في الفصل والباقي تيك هوم كويز ولأمانة كانت متوسطة\n\nالمياجر والفاينلات:\nكومون\n\nإضافات:\nالدكتور حبييييييييييييييب جدا جدا جدا ومتعاون ومتساهل إلا أبعد الحدود يعني من السهل انك تأخذ قريد عالي في الكلاس ورك بس راح تأخذ قريد سئ في المياجر لأن شرحه ميييييييييييييح مع ان تصحيحه للمياجر بطل\n\nلا أنصحك انك تاخذ معه\n\nالقريد النهائي:\nD شرحا\nA+++++ أخلاقا وتعاملا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1098017-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadeem-malik/94443/15", "user": "Chemist", "ts": 1348505393000, "tid": 94443, "pn": 15}}]}', 1348505393000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-math202', 'stk-moh_ammed', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m118565", "n": "Dr. Abdulilah Kadri", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 - Term 221\n\nالتحضير: ينادي على الأسماء في منتصف وقت المحاضرة تقريبا، إذا تأخرت لدقائق معدودة ماعندك مشكلة…أحيانا أشوف ناس يتأخرون كثير والدكتور يطلب منهم مقابلته بعد انتهاء المحاضرة بس ماكانت تصير كثير.\n\nالشرح: يستخدم سلايداته ويكتب على السبورة، وفي بداية كل محاضرة يقعد يراجع درس المحاضرة السابقة. بصراحة شرحه مايجذبني وأشوفه عادي جدا بس فيه بعض الطلاب يعجبهم.\n\nالصوت: كل كلامه انجليزي.\n\nالكويزات: عطانا 4 أو 5 كويزات، نسيت كم بالضبط. كويزاته سهلة للأمانة ومايعقدها.\n\nإضافات:\n* الترم هذا كانت المياجر والفاينل خيارات MCQ (الميجر الأول بس كان فيه جزء رتن بس الباقي كله خيارات).\n* الدكتور طيب جدا وخفيف ظل داخل المحاضرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536122-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulilah-kadri/118565/31", "user": "Moh_ammed", "ts": 1673030984000, "tid": 118565, "pn": 31}}]}', 1673030984000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11942-math202', 'stk-user11942', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term192-math202\n\nعلى حد علمي إنه أول مرة يدرس هذا الكورس. عنده أوراق مكتوب فيها المسائل مع الحلول يشرح منها ويكتبها من جديد على السبورة. وشرحه جيد جداً. واختبرنا معه كويز واحد قبل كورونا وكان سهل يميل للصعوبة. لكنه دقيق بالتصحيح ومايدف خصوصًا إن الاختبارات ريتن . يأخذ دقائق زيادة عن الحصة ويعصب على الطلاب إذا طلعوا على الموعد وماكان يراعي إن كثير منهم عنده كلاسات في مباني بعيدة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524264-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/21", "user": "user11942", "ts": 1595846787000, "tid": 118579, "pn": 21}}]}', 1595846787000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-monster77-math202', 'stk-monster77', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m152151", "n": "Dr. J Al-Smail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 - 181\nبنود التقييم :\n\nالتحضير : معظم الايام وتجي ايام مايحضر , ورقة تمر على الطلاب و ما يدقق على التأخير ويسمح بالميك اب , اخر 3 اسابيع ما حضر .\nطريقة الشرح : يكتب على السبورة والافضل تكتب معاه لانه مايرفع شي على البلاك بورد , شرحه ممتاز ومو سريع ويوضح لك كل النقاط تقريبا , ويقول قصة بين فترة وفترة لتغيير جو الكلاس\nالكويزات : عطانا 6 كويزات , مستواها سهل إلا واحد كان شوي فيه صعوبة , ايضا الدكتور عنده هوموركات نفس المذكورة ف السلابس\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+\nالصوت: واضح جدا\nإضافات :\n\nالدكتور جمال من افضل الدكاترة اللي قابلتهم شرحا وخُلُقا, فادني كثير من الناحية العلمية والعملية والقصص اللي يقولوها بجد تكون مفيدة , يقط نكت احيانا لدرجة ان مستحيل يمر كلاس تحس انه ممل .\nمقدر بشكل كبير لظروف الطلاب , اجَل لنا كويزات وهوموركات كثييرة و متساعد في الساعات المكتبية\nتصحيحه خورافي , عادي جدا تشوف درجتك 10+ من اللي كنت متوقعها . بس ملاحظة : لما اقول تصحيحه ممتاز يعني لو اخطأت في حساب حاجة في بداية المسألة وادى ذلك الى الخطأ في بقية المسألة ( رغم ان الخطوات صحيحة ) راح يعطيك 8 او 9 من 10 . بس لو خطواتك بالاساس كلها خطأ فـ لا تترقب منه ان يدفك. لكن يعيبه انه يتاخر في التصحيح ,ياخذ حوالي 8-10 ايام .\nنظام الكلاس وورك عنده يعتمد بشكل كبير على الكويزات و نسبة ضئيلة على الهومورك والغيابات\n\nوفي الختام ما اقول الا الله يعطيه الف عافية , ولا تتردد في انك تنزل عنده اطلاقا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503537-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-al-smail/152151/20", "user": "monster77", "ts": 1544643043000, "tid": 152151, "pn": 20}}]}', 1544643043000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-math202', 'stk-m_nd_m', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m172442", "n": "Dr. Nicolas Hadjisavvas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 - T162\n\nأضيف كم نقطة بسبب اختلاف طريقة الكورس قليلًا (من ناحية الهومورك مثلًا)\n\nتصحيح الدكتور أشد أكثر (ما يظلمك بس كله بالملي)\nالهوموركات أعطانا مجموع 10… يأخذ أفضل 9 و كان متعاون بتسليم الهومورك\n\nنصيحة: راجع ورقتك بعد الميجر/الفاينل إن أمكن + لا تستهين بالهومورك فتأثيرها قوي على الكلاسورك… أنا كنت مغبص بالكويزات لكن مسلم كل الهوموركات و طلعت أعلى من الأفرج\n\nالهوموركات و الكويزات:\nMATH202HW&QUIZZES | تحميل\n\n*أيضًا في إحتمال أن الدكتور ترك الجامعة لأني مالقيت اسمه بالرجيسترار لترم 171… ربما اسمه سيضاف لاحقًا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1476107-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nicolas-hadjisavvas/172442/8", "user": "M_nd_m", "ts": 1499571635000, "tid": 172442, "pn": 8}}]}', 1499571635000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10934-math202', 'stk-user10934', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m172447", "n": "Dr. Ali Duman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(MATH202 (Term 171\n\nالتحضير : يحضر من بداية الكلاس. ميزته يسمح لك تحضر في أي سكشن بس يسجلك متأخر.\n**الشرح **: يشرح النظرية أو القانون (بشكل سريع و سيئ ) و يحل عليها كم مسألة من old exams .\nالصوت و اللغة : الصوت واضح واللغة جيدة و مفهومة.\nتعامله مع الطلاب : جيد، و يقبل أي سؤال من الطلاب.\nكويزاته : سهلة .\n**التصحيح **: عادي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1484885-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ali-duman/172447/7", "user": "user10934", "ts": 1513879754000, "tid": 172447, "pn": 7}}]}', 1513879754000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10518-math202', 'stk-user10518', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m172449", "n": "Dr. Yassir Khalid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 202 - Term 162\n\nالتحضير :\nيوزع ورقة في بداية الكلاس ويستلمها نهاية المحاضرة حتى لو تحضر متأخر ما عنده مشكلة ويقبل بالميك اب\nطريقة الشرح :\nيشرح الكونسبت ويكتب القانون بعد ذلك يبدا بحل المسائل بشكل متدرج من الاسهل الى الاصعب , الشرح واضح\nالكويزات :\n6 كويزات سهلة او متوسطة\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nA\nالصوت:\nواضح ينسمع حتى لو انت جالس اخر الكلاس\nإضافات :\nدكتور حبيب وشرحه ممتاز وفي التصحيح اذا ما زيدك في المياجر على الاقل راح يعطيك حقك طبعا قبل كان متساهل في التصحيح اكثر بس الديبارتمنت حق الماث شددوا عليه\nاذا تقدر تسجل عنده لا تفوته .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472476-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yassir-khalid/172449/7", "user": "user10518", "ts": 1493887420000, "tid": 172449, "pn": 7}}]}', 1493887420000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_mah-math202', 'stk-abdullah_mah', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 202\n182\n\nالتحضير : يحضر نهاية الكلاس و مايسمح للي متأخرين فوق الربع ساعة ب الدخول, احيانا ياخذ زيادة دقيقة او دقيقتين على وقت الكلاس للتحضير في النهاية, ويسمح ب الميك هذا احسن شي.\n\nطريقة الشرح : يستخدم ال surface pro في الشرح على ال one note, شرحه ممتاز و راح يرفع الملفات ع البلاك بورد\n\nالكويزات : اول كوز خلاه عبيط متعمد عشان ينزل الافرج, الكوزات الباقي كانت عادية و المذاكر راح يحل.\n\nالمياجر: كومن, لكن ضروري تروح المكتب تشوف اختبارك عنده, لأن ممكن في حاجة ما انتبه لها و ما اعطاك درجتها\nاو ممكن تحاجج معاه على سؤال منقص عليه كثير , و ما راح يقصر, الميجر الثاني زودني 4 درجات ولا وحدة استحقها لو امشي على السلوشن 😁2:\n\nالفاينلات : ما بعد اختبر ف IDK\n\nالقريد النهائي: A\n\nالصوت: ,واضح و ينسمع من نهاية الكلاس\n\nإضافات: الدكتور حبيب و فاهم, لكن اذا شافك متنح و فيك النوم ممكن يقولك روح غسل , او اذا شاف هالشي يتكرر كثير منك ممكن احيانا يطردك, و نفس الحكاية معا الجوال اول ما يشوفك تطقطق فيه ؟ \" اتفضل اطلع \"\nsooo be careful", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508302-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/14", "user": "Abdullah_MAH", "ts": 1554512653000, "tid": 175799, "pn": 14}}]}', 1554512653000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-3mran-math202', 'stk-3mran', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202\nTERM182\n\nالتحضير: يحضر بنهاية المحاضرة، ومايدخل المتأخرين اكثر من ١٠ دقايق. والميك اب مسموح\n\nالشرح: عنده نوته يقعد يشرح منها ويحل امثله وللامانة شرحه ممتاز.\n\nالكويزات: للاسف اعطانا بس كويزين خلال السمستر وكل كويز عليه ماتيريال كثييييير. ومهي سهله مره.\n\nالواجبات: عيبه ان اسئلة واجباته جدا كثيره حتى لو الحل عندك تتعب وانت تنقش.\n\nالتصحيح: هنا انا عندي ملاحظة… لمن طلعت درجات الفاينال رحت اراجع ورقتي معاه ولقيته معطيني سؤال كامل صفر وانا حاله صح بس صححه مره ثانيه واخذت فل عليها. وباقي الاسئلة خاسفني فيها شويه حتى لو الجواب صح.\n\nاللي ابغى اقوله لو انت مو شاطر بالماث لا تنزل عنده لان ترى اكتشفت ما يحب الا الدوافير وما يدعم الا الطلاب الدوافير… اما اللي على قد حالهم عادي يخسفهم ويصكهم افات عادي. وانا اعتقد انه كان بيخسفني في الدرجات لانه كان اخذ عني فكرة مو كويسه. لاني مره بس اتأخرت ١٠ دقايق عن الكلاس ببداية السمستر + كنت انعس بعض الاحيان وانام فشكله اخذ فكره عني اني مهمل وقرر يخسفني بكل شي حتى الكلاس وورك اعطاني ١٣ من ٦٠ وانا الصراحه كان عندي ظروف. طبعا كلامي موجه لطلاب اللي تنجح في كورسات الماث ب D و D+\n\nبس ما اقول غير الحمد لله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1517552-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/16", "user": "3mran", "ts": 1575316651000, "tid": 175799, "pn": 16}}]}', 1575316651000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-juha-math202', 'stk-juha', 'MATH 202', 'doc', '{"docs": [{"id": "stk-dr-m181956", "n": "Dr. Dhaker Kroumi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH202 - 222\n\nالتحضير : ترمنا فيه تشديد من القسم على التحضير لذلك صار يحضر شبه يومي، لكن الأيام اللي قبل الإجازات وأيام أسبوع الميجر كان ما يحضر فيها\nطريقة الشرح : يشرح الكونسبت بشكل سريع وباقي الكلاس يحل أمثلة من الكتاب + أولدات وشرحه ممتاز جدا\nالكويزات : سهلة وأغلبها MCQ ويعطي بارشل على الخطوات\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+++++++\nالصوت: واضح جدا ويتكلم عربي غالبا\nإضافات : أفضل دكتور ماث درسني بلا منازع، أخلاق وشرح الله يجزاه الجنة\nالهلب سشن حقته رهيبة ومفيدة جدا وحتى لو فاتتك يرفع نوتة فيها تلخيص للماتيريال وحل أولدات لكل سكشن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536544-math202", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dhaker-kroumi/181956/10", "user": "juha", "ts": 1680631045000, "tid": 181956, "pn": 10}}]}', 1680631045000, 1794834385, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
